export const HVAC_ALL_QUESTIONS = [

  { "id": 1, "art": "Denver CPD Mech Cert §A", "q": "You are applying for the Denver Heating & Ventilating Class A Supervisor Certificate to qualify your company for a new hotel project. What is the minimum total experience required?", "opts": ["4 years total", "6 years total", "8 years total", "10 years total"], "ans": 2, "exp": "Denver requires 8 years total for Class A — 4 years journeyman H&V + 4 years as designer/draftsman/supervisor. Class B (residential) is 6 years total. Exam Trap: students confuse Class A (8 yr) with Class B (6 yr).", "tracks": ["A"], "module": 1 },

  { "id": 2, "art": "Denver CPD Mech Cert §B", "q": "A contractor wants the Class B Heating & Ventilating certificate for residential infill projects in Denver. What is the minimum experience requirement?", "opts": ["4 years (4 field, 0 designer)", "6 years (4 journeyman + 2 designer/supervisor)", "8 years (4 journeyman + 4 designer)", "2 years field experience only"], "ans": 1, "exp": "Class B = 6 years: 4 years journeyman plus 2 years designer/supervisor. Class A doubles the designer portion to 4 years (8 total). Trap: residential is NOT exam-only — it still requires 6 years documented experience.", "tracks": ["B"], "module": 1 },

  { "id": 3, "art": "ICC F29 Exam Spec", "q": "Your friend is scheduling the F29 Master Mechanical exam. How many questions and how much time will he have?", "opts": ["70 questions, 3 hours", "80 questions, 3.5 hours", "100 questions, 4 hours", "120 questions, 5 hours"], "ans": 2, "exp": "F29 (and current G29) = 100 multiple-choice questions in 4 hours, open book, 70% to pass. F32 (residential) is 70 questions in 3 hours. Don't confuse the two formats.", "tracks": ["A"], "module": 1 },

  { "id": 4, "art": "ICC F32 Exam Spec", "q": "The F32 Residential Mechanical exam is structured as:", "opts": ["50 questions / 2 hours / 75% pass", "70 questions / 3 hours / 70% pass", "80 questions / 4 hours / 70% pass", "100 questions / 4 hours / 72% pass"], "ans": 1, "exp": "F32 = 70 questions, 3 hours, 70% to pass, open book. F29 is the larger 100-question / 4-hour version. Pass score is 70% on ICC exams, not 75%.", "tracks": ["B"], "module": 1 },

  { "id": 5, "art": "Denver Class B Scope", "q": "You hold a Denver H&V Class B certificate. Which of the following jobs is OUTSIDE your scope?", "opts": ["A 4-ton split A/C in a single-family home", "A 95 MBtu input furnace in a duplex", "A 6-ton rooftop unit serving a small office", "An IRC townhome HVAC retrofit"], "ans": 2, "exp": "Class B is limited to ≤2-family dwellings, IRC townhomes, Group U occupancies, A/C ≤5 tons, and water heaters ≤100 MBtu input. A 6-ton commercial rooftop requires Class A. Trap: the 5-ton ceiling is hard — 6 tons is over.", "tracks": ["B"], "module": 1 },

  { "id": 6, "art": "Denver CPD Class B Limits", "q": "A Class B residential mechanical supervisor may install a water heater up to what input rating?", "opts": ["75 MBtu", "100 MBtu", "150 MBtu", "199 MBtu"], "ans": 1, "exp": "Class B limit = 100 MBtu input on water heaters. 199 MBtu is the typical residential tankless rating, which exceeds Class B scope and requires Class A or a Gas Service Contractor. Easy trap.", "tracks": ["B", "G"], "module": 1 },

  { "id": 7, "art": "Denver CPD Renewal", "q": "How often must a Denver mechanical supervisor certificate be renewed?", "opts": ["Annually", "Every 2 years", "Every 3 years", "Every 5 years"], "ans": 2, "exp": "Denver supervisor certificates renew every 3 years. CSLB-style 2-year cycles do not apply here — Denver is a 3-year city.", "tracks": ["A", "B", "G"], "module": 1 },

  { "id": 8, "art": "EPA 608 Prereq", "q": "For the Denver Class A Heating & Ventilating Supervisor application, which federal certification must also be on file?", "opts": ["OSHA 30", "EPA Section 608 (any type)", "NATE Core", "ICC G29 only — no federal cert needed"], "ans": 1, "exp": "EPA Section 608 certification is required because Class A scope includes refrigerant handling. Without it, Denver will not issue the H&V Class A certificate. OSHA 30 is industry-standard but not required by Denver CPD.", "tracks": ["A"], "module": 1 },

  { "id": 9, "art": "ICC F33 Exam Spec", "q": "The F33 Master Gas Pipefitter exam qualifies a contractor for which Denver certificate?", "opts": ["Boilermaker Supervisor", "Gas Service Contractor Supervisor", "Refrigeration Class A", "Steam & Hot Water Supervisor"], "ans": 1, "exp": "F33 maps to the Denver Gas Service Contractor Supervisor certificate (gas + liquid fuel piping, controls, commercial cooking, ≤100 MBtu water heaters). Boilermaker and Steam & Hot Water both fall under F29.", "tracks": ["G"], "module": 1 },

  { "id": 10, "art": "Denver CPD Open Book", "q": "You walk into the Denver F29 exam. Which of the following are you allowed to bring as references?", "opts": ["Any HVAC textbook", "2018 IMC and 2018 IFGC only (no marginal notes)", "2018 IMC, 2018 IFGC, and a Denver amendment packet — bound, tabbed, highlighted", "2024 IMC because Denver permits use 2024"], "ans": 2, "exp": "Open-book ICC exams allow the referenced code editions (IMC + IFGC) with tabs, highlights, and underlining. Loose notes are usually disallowed but bound, printed code books with tabs are fine. The exam version is the older edition (2018) even though Denver field permits use 2024.", "tracks": ["A", "B", "G"], "module": 1 },

  { "id": 11, "art": "Denver CPD Class A Alt Path", "q": "A contractor has 4 years of journeyman H&V plus only 2 years of designer experience. He wants Class A. What does he need?", "opts": ["He already qualifies — 6 years is enough", "He needs 2 more years as designer/supervisor (total 8)", "He needs 4 more years of journeyman work", "Class A only requires the F29 exam — no experience"], "ans": 1, "exp": "Class A = 8 years total (4 + 4). With only 4 + 2 he is 2 designer-years short. The alt path (4 yr field + 2 yr designer = 6 yr) qualifies him for Class B, not A. Always count both halves.", "tracks": ["A"], "module": 1 },

  { "id": 12, "art": "Denver Boilermaker Scope", "q": "Which Denver supervisor certificate is required to install and supervise large steam boilers in a commercial building?", "opts": ["Class B H&V", "Refrigeration Class B", "Steam & Hot Water Supervisor (F29)", "Gas Service Contractor (F33)"], "ans": 2, "exp": "Steam & Hot Water Supervisor is its own Denver Class A-tier certificate, exam = F29, 8 years experience. F33 covers the gas piping TO the boiler but not the boiler itself. A common scope-overlap trap.", "tracks": ["A"], "module": 1 },

  { "id": 13, "art": "Denver CPD Application", "q": "To qualify a company for a Denver mechanical permit, the listed supervisor must:", "opts": ["Be a W-2 employee or owner with regular full-time involvement", "Only sign the application — no involvement needed", "Hold the certificate for 10+ years", "Be physically on site during all work"], "ans": 0, "exp": "Denver requires the qualifying supervisor to be a bona fide employee or owner regularly engaged in the company's business — no certificate rentals. On-site presence is not required, but supervisory control is.", "tracks": ["A", "B", "G"], "module": 1 },

  { "id": 14, "art": "IMC Ch.1", "q": "On the open-book F29 exam you need to look up the scope of the IMC fast. Which chapter contains 'Administration' including scope and applicability?", "opts": ["Chapter 1", "Chapter 3", "Chapter 10", "Chapter 13"], "ans": 0, "exp": "IMC Chapter 1 = Administration (scope, applicability, permits). Chapter 3 = General Regulations. Knowing chapter-by-topic mapping is the open-book exam strategy that wins seconds.", "tracks": ["A", "B"], "module": 2 },

  { "id": 15, "art": "IMC Ch.4 vs Ch.5", "q": "You're sizing outdoor air for a hotel ballroom. Which IMC chapter contains Table 403.3.1.1?", "opts": ["Chapter 3 — General Regulations", "Chapter 4 — Ventilation", "Chapter 5 — Exhaust", "Chapter 6 — Duct Systems"], "ans": 1, "exp": "IMC Chapter 4 = Ventilation, including Table 403.3.1.1 (outdoor air rates per occupancy). Chapter 5 = Exhaust (hoods, dryers, hazardous). Chapter 6 = Ducts. Knowing which chapter holds which table is the open-book advantage.", "tracks": ["A"], "module": 2 },

  { "id": 16, "art": "IFGC Ch.3", "q": "Combustion air provisions for fuel-gas appliances live in which IFGC chapter?", "opts": ["Chapter 2 — Definitions", "Chapter 3 — General Regulations", "Chapter 4 — Gas Piping", "Chapter 5 — Venting"], "ans": 1, "exp": "IFGC Chapter 3 contains combustion air (304), appliance location (303), and general regulations. Chapter 4 is pipe sizing tables; Chapter 5 is venting.", "tracks": ["A", "B", "G"], "module": 2 },

  { "id": 17, "art": "IFGC Ch.4", "q": "Where in the IFGC do you find Table 402.4 for sizing natural gas piping?", "opts": ["Chapter 3", "Chapter 4 — Gas Piping Installations", "Chapter 5", "Chapter 6"], "ans": 1, "exp": "IFGC Chapter 4 = Gas Piping Installations, including all the 402.4 sizing tables. Memorize: Ch.3=combustion air, Ch.4=piping, Ch.5=venting, Ch.6=specific appliances.", "tracks": ["A", "B", "G"], "module": 2 },

  { "id": 18, "art": "IMC vs IFGC Authority", "q": "A gas-fired furnace is being installed. The IMC and IFGC both contain related provisions. Which code governs the gas piping to the appliance?", "opts": ["IMC Chapter 9 — Specific Appliances", "IFGC Chapter 4 — Gas Piping", "IBC Chapter 28", "Whichever the AHJ chooses"], "ans": 1, "exp": "Gas piping is always IFGC, even for furnaces. The IMC covers the furnace install (location, clearance, condensate, vent connector), and the IFGC governs the gas piping. Knowing the split prevents wasted lookup time.", "tracks": ["A", "B", "G"], "module": 2 },

  { "id": 19, "art": "IMC 102.1", "q": "When an IMC provision conflicts with a more specific provision elsewhere in the IMC, which controls?", "opts": ["The general provision", "The more specific provision", "The AHJ chooses", "The provision adopted first"], "ans": 1, "exp": "IMC 102.1 — the more specific provision governs over the general. This is a fundamental code-reading rule that shows up on exams as a Section 102 question.", "tracks": ["A", "B"], "module": 2 },

  { "id": 20, "art": "IMC Ch.13 / IFGC Ch.7", "q": "Where would you look for IMC provisions on solar heating and combustion air for special appliances?", "opts": ["Chapter 1 Administration", "Chapter 13 — Special Piping & Storage Systems", "Chapter 9 — Specific Appliances", "Chapter 14"], "ans": 2, "exp": "IMC Chapter 9 = Specific Appliances (furnaces, boilers, room heaters, fireplaces, solar). Chapter 13 covers fuel oil piping/storage. Use the chapter index inside your tabbed book.", "tracks": ["A", "B"], "module": 2 },

  { "id": 21, "art": "Denver Amendment Strategy", "q": "On the open-book Denver exam, you find an IMC base-code requirement and a Denver amendment that's more restrictive. Which applies for permit purposes?", "opts": ["IMC base code", "Denver amendment (the more restrictive local rule)", "Whichever is older", "Both — average them"], "ans": 1, "exp": "Denver amendments override base IMC/IFGC where they apply. The ICC exam itself tests base code (2018), but the Denver field permit follows Denver amendments. Know both for real-world compliance.", "tracks": ["A", "B", "G"], "module": 2 },

  { "id": 22, "art": "IMC 202 / IFGC 202", "q": "You're sizing a furnace. The label reads '100,000 Btu/hr input.' How is this commonly expressed in HVAC shorthand?", "opts": ["100 kW", "100 MBtu/hr or 100 MBH", "1 therm/hr", "100 cfm"], "ans": 1, "exp": "MBtu = 1,000 Btu (M = Roman 1,000), so 100,000 Btu/hr = 100 MBtu/hr = 100 MBH. NOT mega-Btu. Confusing the M with mega is a top distractor.", "tracks": ["A", "B", "G"], "module": 3 },

  { "id": 23, "art": "IFGC 202 'Therm'", "q": "A residential gas bill shows usage of 80 therms. One therm equals:", "opts": ["1,000 Btu", "10,000 Btu", "100,000 Btu", "1,000,000 Btu"], "ans": 2, "exp": "1 therm = 100,000 Btu. 1,000 Btu = 1 MBtu (one MBH unit). Utility billing uses therms; equipment is rated in Btu/hr or MBH.", "tracks": ["A", "B", "G"], "module": 3 },

  { "id": 24, "art": "IMC 202 'Plenum'", "q": "Per IMC 202, a 'plenum' is best defined as:", "opts": ["Any duct over 12 inches in diameter", "An enclosed portion of a building used for environmental air movement, other than ducts", "The return air grille", "The mechanical room itself"], "ans": 1, "exp": "Plenum = an enclosed space (often ceiling cavity, raised floor, or chase) used for air distribution other than the duct system. Plenum-rated materials are required for wiring in plenums per NEC + IMC 602.", "tracks": ["A", "B"], "module": 3 },

  { "id": 25, "art": "IFGC 202 Categories", "q": "A condensing gas furnace exhausts cool, wet flue gases through plastic vent pipe. This is which appliance vent category?", "opts": ["Category I — non-positive, non-condensing", "Category II — non-positive, condensing", "Category III — positive, non-condensing", "Category IV — positive, condensing"], "ans": 3, "exp": "Category IV = positive vent pressure + condensing (cool flue gas). High-efficiency furnaces (90%+) are Category IV and use PVC/CPVC/polypropylene. Category I = old atmospheric draft natural-vent furnaces.", "tracks": ["A", "B"], "module": 3 },

  { "id": 26, "art": "IMC 202 'Return Air'", "q": "Return air is defined as air:", "opts": ["Drawn from outside for ventilation", "Removed from the conditioned space and recirculated to the heating/cooling system", "Discharged to the outdoors as exhaust", "Provided as makeup air"], "ans": 1, "exp": "Return air = conditioned-space air returning to the equipment for re-tempering. Outdoor air, exhaust, and makeup are three other defined air streams. Know the four streams cold.", "tracks": ["A", "B"], "module": 3 },

  { "id": 27, "art": "IMC 202 'Makeup Air'", "q": "You're installing a 600 cfm range hood. The code-required air introduced to compensate for the exhausted air is called:", "opts": ["Return air", "Outdoor air for ventilation", "Makeup air", "Plenum air"], "ans": 2, "exp": "Makeup air = air introduced to replace air exhausted by hoods, dryers, or other exhaust systems. Required by IMC 505.2 when residential exhaust exceeds 400 cfm.", "tracks": ["A", "B"], "module": 3 },

  { "id": 28, "art": "IMC Ch.4 'CFM'", "q": "A '5-ton' A/C system has a nominal cooling capacity of:", "opts": ["12,000 Btu/hr", "36,000 Btu/hr", "60,000 Btu/hr", "100,000 Btu/hr"], "ans": 2, "exp": "1 ton of cooling = 12,000 Btu/hr (the heat absorbed by melting 1 ton of ice in 24 hr). 5 tons = 60,000 Btu/hr. This is the Class B residential ceiling — Class A required above.", "tracks": ["A", "B"], "module": 3 },

  { "id": 29, "art": "IMC 202 'Outdoor Air'", "q": "Per IMC definitions, 'outdoor air' is:", "opts": ["Air from outside the building taken in for ventilation", "Recirculated return air", "Exhaust air discharged to outside", "Combustion air"], "ans": 0, "exp": "Outdoor air = ambient air brought into the building for ventilation (ASHRAE 62.1 rates apply). Combustion air is a separate stream supplied to fuel-burning appliances per IFGC 304.", "tracks": ["A", "B", "G"], "module": 3 },

  { "id": 30, "art": "IMC 306.1", "q": "You're installing a rooftop air handler on a 22-foot-tall office in Denver. Per IMC 306, what must be provided for service access?", "opts": ["A ladder only", "A permanent walkway because the equipment is above 16 ft", "Nothing — rooftop is exempt", "A telescoping ladder kept on site"], "ans": 1, "exp": "IMC 306.5 requires a permanent walkway for rooftop equipment located more than 16 ft above grade. A permanent service receptacle within 25 ft and within sight is also required. 22 ft > 16 ft triggers both.", "tracks": ["A", "B"], "module": 4 },

  { "id": 31, "art": "IMC 306.5", "q": "In addition to a permanent walkway, a rooftop service receptacle must be:", "opts": ["Within 50 ft of the equipment", "Within 25 ft and within sight of the equipment", "On the building exterior wall only", "Inside the mechanical room"], "ans": 1, "exp": "IMC 306.5: receptacle within 25 ft AND within sight of the rooftop equipment. The within-sight rule matters: it must be visible to the technician at the equipment.", "tracks": ["A", "B"], "module": 4 },

  { "id": 32, "art": "IMC 306.1 Clearance", "q": "You're laying out a basement furnace closet. What is the minimum service working clearance dimension in front of the appliance per IMC 306.1?", "opts": ["18 inches wide × 24 inches deep", "24 inches wide × 24 inches deep", "30 inches wide × 30 inches deep", "36 inches wide × 36 inches deep"], "ans": 2, "exp": "IMC 306.1: 30 in × 30 in × 78 in high working space in front of equipment for service. Confusing this with NEC's 36 in electrical working space is a common trap.", "tracks": ["A", "B"], "module": 4 },

  { "id": 33, "art": "IMC 307.2.1", "q": "A suspended air handler above a finished ceiling requires an auxiliary drain pan because:", "opts": ["The primary drain might freeze", "Leakage from the primary drain could damage finishes below", "It's optional — only required outdoors", "Code requires only a float switch, not a pan"], "ans": 1, "exp": "IMC 307.2.1 requires either an auxiliary drain pan OR a water-level detection (float switch) on suspended air handlers to prevent overflow damage. A pan plus a separate emergency drain line is the bulletproof method.", "tracks": ["A", "B"], "module": 4 },

  { "id": 34, "art": "IMC 307.2.3", "q": "Condensate drain pipe must slope toward discharge at a minimum of:", "opts": ["1/16 inch per foot", "1/8 inch per foot", "1/4 inch per foot", "1/2 inch per foot"], "ans": 1, "exp": "IMC 307.2.3 — minimum 1/8 in/ft (1% slope) for condensate. Trap: 1/4 in/ft is the kitchen hood slope (IMC 506.3.7) — don't mix them up.", "tracks": ["A", "B"], "module": 4 },

  { "id": 35, "art": "IMC 307.2.2", "q": "Which of the following materials is NOT permitted for a condensate drain line?", "opts": ["PVC", "CPVC", "ABS", "Galvanized steel"], "ans": 3, "exp": "IMC 307.2.2 permits PVC, CPVC, ABS, polypropylene, and copper. Galvanized steel is not approved — condensate is mildly acidic and will corrode it. Trap: students assume any drain pipe works.", "tracks": ["A", "B"], "module": 4 },

  { "id": 36, "art": "IMC 304.6", "q": "An appliance is installed in a Denver attic. What is required for access?", "opts": ["A 22 in × 30 in opening, level platform, and switch + light", "Just the attic hatch", "A pull-down stair only", "No requirements — attic appliances are exempt"], "ans": 0, "exp": "IMC 306.3 attic access: 22 in × 30 in opening (minimum), 24 in passageway, level service platform, lighted switch at the entrance. A common multi-part question.", "tracks": ["A", "B"], "module": 4 },

  { "id": 37, "art": "IMC 303.3", "q": "A fuel-burning appliance may NOT be installed in which of the following dwelling locations?", "opts": ["Detached garage", "Sleeping room or bathroom (unless direct-vent or sealed combustion)", "Basement", "Furnace closet"], "ans": 1, "exp": "IMC 303.3 / IFGC 303.3 prohibits fuel-fired appliances in sleeping rooms or bathrooms unless they are direct-vent, sealed-combustion, or in an enclosed space with outside-only combustion air. Atmospheric appliances cannot share air with sleepers.", "tracks": ["A", "B", "G"], "module": 4 },

  { "id": 38, "art": "IMC 304.10", "q": "An appliance installed in a private residential garage must have its ignition source elevated above the garage floor by at least:", "opts": ["6 inches", "12 inches", "18 inches", "24 inches"], "ans": 2, "exp": "IMC 304.3 / IFGC 305.3 — 18 inches above the garage floor for ignition sources. This is to keep ignition above potential gasoline vapor accumulation. 18 in is a top-tested number.", "tracks": ["A", "B"], "module": 4 },

  { "id": 39, "art": "IMC 305", "q": "Equipment installed outdoors in Denver must be:", "opts": ["Painted any color", "Listed for outdoor installation and protected from snow accumulation per the manufacturer", "Enclosed in a heated cabinet always", "Limited to summer use"], "ans": 1, "exp": "IMC 305 requires outdoor equipment be listed for outdoor use. Denver's high-altitude, freeze/thaw, and snow-load conditions make manufacturer instructions critical — and Denver amendments often add freeze-protection requirements.", "tracks": ["A", "B"], "module": 4 },

  { "id": 40, "art": "IMC 306.2", "q": "You're framing a furnace closet in a single-family home. The furnace requires 30 in × 30 in working space. The closet door opens 24 inches wide. Is this compliant?", "opts": ["Yes — closets are exempt", "No — the working space must be unobstructed and accessible", "Yes — provided the door swings outward", "Yes — provided there's a window"], "ans": 1, "exp": "IMC 306.1: working space must be unobstructed and accessible. A 24 in door blocks access to a 30 in working space. Door must allow full access to the required clearance. This trap catches framers all the time.", "tracks": ["A", "B"], "module": 4 },

  { "id": 41, "art": "IMC 306.4", "q": "A heating appliance installed on the ground requires what kind of base?", "opts": ["No base — set directly on soil", "Level non-combustible base", "Wood base treated for moisture", "6 inches of pea gravel"], "ans": 1, "exp": "IMC 306.4 — level, solid, non-combustible base. Outdoor units on soil generally sit on a concrete pad or factory-approved equipment pad. Wood is never acceptable for fuel-fired equipment.", "tracks": ["A", "B"], "module": 4 },

  { "id": 42, "art": "IFGC 304.5.3.3", "q": "You are providing combustion air to a Denver utility room by combining spaces on the same story (indoor air method). The mechanical room is open to an adjacent room via two permanent openings near the top and bottom. The combined appliance input is 200,000 Btu/hr. What is the minimum size of EACH opening?", "opts": ["50 sq in", "100 sq in", "150 sq in", "200 sq in"], "ans": 3, "exp": "Indoor combining-spaces method (IFGC 304.5.3.3): each opening = 1 sq in per 1,000 Btu/hr of total appliance input, MINIMUM 100 sq in. 200,000 ÷ 1,000 = 200 sq in each. Don't confuse this with the OUTDOOR two-opening method (IFGC 304.6.1), which uses 1 sq in / 4,000 Btu/hr per opening (vertical duct / direct outdoors) or 1 sq in / 2,000 Btu/hr (horizontal duct). Top exam trap.", "tracks": ["A", "B", "G"], "module": 5 },

  { "id": 43, "art": "IFGC 304.6.2", "q": "Using the single-opening OUTDOOR method for combustion air, you must provide:", "opts": ["1 sq in per 1,000 Btu/hr", "1 sq in per 2,000 Btu/hr", "1 sq in per 3,000 Btu/hr", "1 sq in per 4,000 Btu/hr"], "ans": 2, "exp": "IFGC 304.6.2 single outdoor opening = 1 sq in per 3,000 Btu/hr. Compare: outdoor two-opening (direct/vertical, §304.6.1) = 1 sq in / 4,000 Btu/hr per opening; horizontal-duct two-opening = 1 sq in / 2,000 Btu/hr per opening. The 1/1,000 denominator is the INDOOR combining-spaces rule (§304.5.3.3) — different scenario. Exam Trap #2.", "tracks": ["A", "B", "G"], "module": 5 },

  { "id": 44, "art": "IFGC 304.6.2", "q": "A single OUTDOOR combustion-air opening for a mechanical room with 150,000 Btu/hr total appliance input must be at least:", "opts": ["50 sq in", "75 sq in", "150 sq in", "300 sq in"], "ans": 0, "exp": "IFGC 304.6.2 single outdoor opening = 1 sq in / 3,000 Btu/hr: 150,000 ÷ 3,000 = 50 sq in. For comparison, outdoor two-opening (vertical/direct, §304.6.1) would be 150,000 ÷ 4,000 = ~38 sq in calculated → 100 sq in min-area floor each. Always identify which method is being asked.", "tracks": ["A", "B", "G"], "module": 5 },

  { "id": 45, "art": "IFGC 304.6.1", "q": "For the indoor air (standard method) for combustion air, the required room volume is:", "opts": ["10 ft³ per 1,000 Btu/hr", "25 ft³ per 1,000 Btu/hr", "50 ft³ per 1,000 Btu/hr", "100 ft³ per 1,000 Btu/hr"], "ans": 2, "exp": "IFGC 304.6.1: 50 ft³ per 1,000 Btu/hr of total appliance input for the standard indoor air method. This presumes 'unknown infiltration.' Tight construction requires outdoor air.", "tracks": ["A", "B", "G"], "module": 5 },

  { "id": 46, "art": "IFGC 304.6", "q": "A mechanical room contains a 100,000 Btu/hr furnace and an 80,000 Btu/hr water heater. Using the indoor (standard) method, what is the minimum room volume?", "opts": ["5,000 ft³", "6,000 ft³", "9,000 ft³", "12,000 ft³"], "ans": 2, "exp": "Total input = 180,000 Btu/hr. Volume = 180 × 50 = 9,000 ft³. That's a 9 ft ceiling × 1,000 sq ft — usually not realistic, which is why outdoor combustion air is more common.", "tracks": ["A", "B", "G"], "module": 5 },

  { "id": 47, "art": "IFGC 304.5.3.1", "q": "Combustion air openings communicating with the outdoors must be located so the top opening is within:", "opts": ["6 inches of the ceiling", "12 inches of the ceiling", "18 inches of the ceiling", "24 inches of the ceiling"], "ans": 1, "exp": "IFGC 304.5.3.1: top opening within 12 in of the ceiling; bottom opening within 12 in of the floor. Both ends matter — flue gases rise, makeup falls.", "tracks": ["A", "B", "G"], "module": 5 },

  { "id": 48, "art": "IFGC 304.5.3.1", "q": "The bottom combustion air opening must be located within what distance of the floor?", "opts": ["6 inches", "12 inches", "18 inches", "24 inches"], "ans": 1, "exp": "Both top AND bottom openings must be within 12 in of their respective surfaces (ceiling for top, floor for bottom). This drives natural convection of combustion air.", "tracks": ["A", "B", "G"], "module": 5 },

  { "id": 49, "art": "IFGC 304.7", "q": "Mechanical combustion air supplied by a fan must provide at least:", "opts": ["0.15 cfm per 1,000 Btu/hr", "0.25 cfm per 1,000 Btu/hr", "0.35 cfm per 1,000 Btu/hr", "0.50 cfm per 1,000 Btu/hr"], "ans": 2, "exp": "IFGC 304.7 — 0.35 cfm per 1,000 Btu/hr for mechanical (fan-supplied) combustion air. A common exam calculation. The blower must also be interlocked with the appliance.", "tracks": ["A", "B", "G"], "module": 5 },

  { "id": 50, "art": "IFGC 304.7", "q": "A 150,000 Btu/hr boiler requires mechanical combustion air. What is the minimum fan cfm?", "opts": ["35 cfm", "52.5 cfm", "75 cfm", "105 cfm"], "ans": 1, "exp": "150 × 0.35 = 52.5 cfm minimum. The fan must be interlocked so the appliance cannot fire without the combustion-air fan running.", "tracks": ["A", "B", "G"], "module": 5 },

  { "id": 51, "art": "IFGC 304.5", "q": "Each combustion air opening (either method) must be at least:", "opts": ["10 sq in", "50 sq in", "100 sq in", "144 sq in"], "ans": 2, "exp": "Minimum 100 sq in EACH opening regardless of calculation result — a floor enforced by IFGC 304.5 to ensure adequate flow at low fire conditions. Easy to forget.", "tracks": ["A", "B", "G"], "module": 5 },

  { "id": 52, "art": "IFGC 304.10", "q": "When metal louvers cover combustion air openings, you must assume what free area unless tested?", "opts": ["100%", "75%", "50% (wood) or 75% (metal)", "25%"], "ans": 2, "exp": "Default louver free area: 25% wood, 75% metal. Apply to the calculated opening size — a 100 sq in metal opening with a louver requires 100 ÷ 0.75 = 134 sq in louver. Students forget the louver derating.", "tracks": ["A", "B", "G"], "module": 5 },

  { "id": 53, "art": "IFGC 304", "q": "Direct-vent (sealed combustion) appliances are exempt from combustion air requirements because:", "opts": ["They use room air", "They draw combustion air directly from outdoors through sealed piping", "They produce no flue gases", "They are listed for outdoor use only"], "ans": 1, "exp": "Direct-vent appliances pipe combustion air in from outside and flue gas out — fully sealed from room air. No combustion air provisions per IFGC 304 are required.", "tracks": ["A", "B", "G"], "module": 5 },

  { "id": 54, "art": "IFGC 304.6.1", "q": "A Denver mechanical room is using OUTDOOR air through two openings communicating directly with outdoors (vertical duct). The total appliance input is 300,000 Btu/hr. The contractor sizes each opening at 200 sq in. Is this compliant?", "opts": ["Yes — 200 sq in exceeds both the 75 sq in calculated minimum and the 100 sq in minimum floor", "No — each opening must be at least 300 sq in", "Yes — only one opening is required", "No — single-opening method requires 100 sq in"], "ans": 0, "exp": "OUTDOOR two-opening method (IFGC 304.6.1, direct or vertical duct) = 1 sq in per 4,000 Btu/hr per opening: 300,000 ÷ 4,000 = 75 sq in calculated, bumped to 100 sq in by the minimum-area floor. 200 sq in is well above the requirement. Top exam trap — students confuse this with the indoor combining-spaces rule (1 sq in / 1,000 Btu/hr, §304.5.3.3) or the horizontal-duct rule (1 sq in / 2,000 Btu/hr).", "tracks": ["A", "B", "G"], "module": 5 },

  { "id": 55, "art": "IFGC 304", "q": "In a tightly built modern Denver home, the indoor (standard) method for combustion air is:", "opts": ["Always allowed", "Allowed only when infiltration rate is unknown", "Required by Denver amendment", "Prohibited — must use outdoor air"], "ans": 1, "exp": "IFGC 304.6 is for unknown infiltration. Modern tight construction has low infiltration that fails the volume calc, so outdoor combustion air is almost always required in new builds. A Denver tight-envelope reality.", "tracks": ["A", "B", "G"], "module": 5 },

  { "id": 56, "art": "IFGC 503.10.1", "q": "You're installing a Type B gas vent through a wood-framed chase. What is the minimum clearance from the Type B vent to combustibles?", "opts": ["0 inches", "1 inch", "6 inches", "18 inches"], "ans": 1, "exp": "Type B gas vent = 1 in clearance to combustibles (listed). Single-wall metal vent = 6 in. Top 12 Exam Trap #4 — students mix the two up. Always confirm Type B vs single-wall.", "tracks": ["A", "B", "G"], "module": 6 },

  { "id": 57, "art": "IFGC 503.10.2", "q": "Single-wall metal vent connector clearance to combustibles is:", "opts": ["1 inch", "3 inches", "6 inches", "9 inches"], "ans": 2, "exp": "Single-wall metal = 6 in clearance to combustibles. Type B = 1 in. This pair is among the most commonly tested clearance distinctions. Exam Trap #4.", "tracks": ["A", "B", "G"], "module": 6 },

  { "id": 58, "art": "IMC 804.3 (3-2-10)", "q": "A chimney terminates 4 ft above the roof penetration. There is a 5 ft tall parapet wall located 8 ft horizontally from the chimney. Is this code compliant?", "opts": ["Yes — chimney clears 3 ft above roof penetration", "No — 3-2-10 requires chimney to extend 2 ft above any portion of building within 10 ft horizontally", "Yes — chimneys only need to clear the roof penetration", "No — chimney must be 5 ft above roof"], "ans": 1, "exp": "3-2-10 rule: at least 3 ft above the roof penetration AND 2 ft above ANYTHING within 10 ft horizontally. 5 ft parapet at 8 ft requires chimney top at least 7 ft. 4 ft fails. Top 12 Exam Trap #5.", "tracks": ["A", "B", "G"], "module": 6 },

  { "id": 59, "art": "IMC 804.3", "q": "The 3-2-10 chimney termination rule states the chimney must extend:", "opts": ["3 ft above any roof penetration only", "2 ft above any roof penetration, 3 ft above structures within 10 ft", "3 ft above the roof penetration AND 2 ft above any portion of the building within 10 ft horizontally", "10 ft above the ridge"], "ans": 2, "exp": "3-2-10: 3 ft above the point of penetration AND 2 ft above any building portion within a 10 ft horizontal radius. All three numbers matter. Exam Trap #5.", "tracks": ["A", "B", "G"], "module": 6 },

  { "id": 60, "art": "IFGC 503.5.4", "q": "A single-wall vent connector serves a Category I gas water heater. The horizontal connector run must not exceed:", "opts": ["50% of vertical vent height", "75% of vertical vent height", "100% of vertical vent height", "No limit if listed"], "ans": 1, "exp": "IFGC 503.5.4 / IMC 803.5: vent connector horizontal run ≤ 75% of total vertical vent height. Long horizontal runs kill draft.", "tracks": ["A", "B", "G"], "module": 6 },

  { "id": 61, "art": "IMC 801.18", "q": "A Category IV (condensing) gas furnace may be vented through:", "opts": ["Type B vent only", "Single-wall galvanized vent", "PVC, CPVC, or polypropylene per manufacturer listing", "Brick chimney"], "ans": 2, "exp": "Condensing appliances produce acidic condensate and low-temp flue gas — only listed plastic vent (PVC/CPVC/PP) per the manufacturer's installation manual. Type B is for Category I (atmospheric).", "tracks": ["A", "B"], "module": 6 },

  { "id": 62, "art": "IFGC 503", "q": "A masonry chimney serving a Category I gas appliance requires what minimum clearance from interior combustibles?", "opts": ["0 inches", "1 inch", "2 inches", "6 inches"], "ans": 2, "exp": "Masonry chimney: 2 in clearance to combustibles interior; 1 in exterior. Distinct from Type B (1 in) and single-wall (6 in). Don't confuse masonry with metal vent rules.", "tracks": ["A", "B", "G"], "module": 6 },

  { "id": 63, "art": "IFGC 404.6", "q": "You're routing gas piping in a Denver retrofit and want to run it inside an unused masonry chimney for protection. This is:", "opts": ["Allowed if the chimney is lined", "Allowed if the gas pipe is wrapped", "Prohibited by IFGC 404.6", "Allowed only with AHJ approval"], "ans": 2, "exp": "IFGC 404.6 prohibits gas piping inside any chimney or vent. Hot flue gas (or future use of the chimney) plus an undetected leak = explosion risk. Hard prohibition.", "tracks": ["A", "B", "G"], "module": 6 },

  { "id": 64, "art": "IFGC 503", "q": "Two appliances are commonly vented into the same Type B vent. To size the common vent you would use:", "opts": ["The sum of inputs only", "IFGC Tables 504.2 / 504.3 for common venting", "Manufacturer specs only", "IMC Chapter 6 duct tables"], "ans": 1, "exp": "IFGC 504 common-venting tables size the connector and common vent based on individual inputs, vent height, and connector rise. Look up the table — don't guess.", "tracks": ["A", "B", "G"], "module": 6 },

  { "id": 65, "art": "IFGC 503.6.6", "q": "A gas vent terminates above a roof. The required vent cap is intended to:", "opts": ["Reduce flue gas temperature", "Prevent rain entry and downdraft, while permitting upward flue gas flow", "Increase backpressure", "Filter particulates"], "ans": 1, "exp": "Listed vent caps protect from rain, snow, debris, and downdraft while allowing flue products out. Caps are listed for the specific vent type — don't mix-and-match.", "tracks": ["A", "B", "G"], "module": 6 },

  { "id": 66, "art": "IMC 804.2", "q": "Type B vent terminating in an area with snow accumulation in Denver must terminate at least:", "opts": ["6 inches above the roof", "Per Table 804.3.4 based on roof pitch", "Exactly 3 ft above the roof in all cases", "12 inches above the snow line"], "ans": 1, "exp": "Termination heights are taken from Table 804.3.4, which adjusts by roof pitch. Steeper roofs require taller terminations. Denver's snow loads make this critical.", "tracks": ["A", "B", "G"], "module": 6 },

  { "id": 67, "art": "IFGC 503", "q": "A draft hood-equipped (Category I) gas appliance shares a chimney with a fan-assisted Category I appliance. When sizing common vent, use which table set?", "opts": ["Tables 504.2 (fan-assisted) and 504.3 (combined)", "Table 504.1 only", "IMC Table 802", "Manufacturer's catalog"], "ans": 0, "exp": "504.2 = fan-assisted appliance(s); 504.3 = combined (one or more draft hood + fan-assisted). Match the appliance combination to the right table family.", "tracks": ["A", "B", "G"], "module": 6 },

  { "id": 68, "art": "IMC 801.6", "q": "All vent connector joints must be:", "opts": ["Taped only", "Mechanically secured with at least 3 screws per joint", "Welded", "Glued with mastic"], "ans": 1, "exp": "IMC 801.6 / IFGC 503.5.7: mechanically fastened with at least 3 sheet-metal screws (or equivalent) per joint to prevent disconnection from thermal cycling. Screws on Type B do NOT penetrate the inner liner.", "tracks": ["A", "B", "G"], "module": 6 },

  { "id": 69, "art": "IFGC 503.10.5", "q": "You can reduce the 6-in clearance for a single-wall metal vent connector by:", "opts": ["Using listed clearance reduction methods (e.g., 1-in air space + 24 ga sheet metal)", "Wrapping with fiberglass", "Painting it", "No reduction is allowed"], "ans": 0, "exp": "IFGC Table 308.2 lists field-applied clearance reductions: e.g., 24 ga sheet metal with 1-in spaced air gap allows 67% reduction. Must follow the listed methodology.", "tracks": ["A", "B", "G"], "module": 6 },

  { "id": 70, "art": "IMC 902 / IFGC 614", "q": "You're installing a residential gas furnace. Per code, the gas shutoff valve must be located:", "opts": ["Anywhere on the gas line", "Within 6 ft of the appliance, in the same room, accessible", "At the meter only", "Inside the appliance jacket"], "ans": 1, "exp": "IFGC 409.5: shutoff valve within 6 ft of each appliance, same room, accessible. The 6 ft window is testable.", "tracks": ["A", "B", "G"], "module": 7 },

  { "id": 71, "art": "IMC 903.3", "q": "An unvented room heater is being considered for a Denver bedroom. This is:", "opts": ["Allowed only if listed and meeting IMC 904", "Always allowed up to 30,000 Btu/hr", "Prohibited in sleeping rooms by IMC 303.3", "Allowed only if a CO detector is present"], "ans": 2, "exp": "IMC 303.3 + IFGC 303.3 prohibit fuel-fired appliances in sleeping rooms unless direct-vent. Unvented room heaters dump combustion products into the space — never allowed in bedrooms.", "tracks": ["A", "B"], "module": 7 },

  { "id": 72, "art": "IMC 903.2", "q": "A decorative gas-log set is installed in an existing masonry fireplace. Per code, the damper must be:", "opts": ["Operable and adjustable", "Fully removed or permanently fixed in the open position", "Closed during operation", "Hinged with auto-close"], "ans": 1, "exp": "IFGC 614.6 / IMC 903.2 — unvented or vented decorative gas appliances require the damper to be fixed open or removed to prevent CO buildup. Don't let homeowners shut the damper.", "tracks": ["A", "B"], "module": 7 },

  { "id": 73, "art": "IMC 904", "q": "Unvented room heaters are limited to a maximum input of:", "opts": ["10,000 Btu/hr", "20,000 Btu/hr", "40,000 Btu/hr", "No limit if AGA approved"], "ans": 2, "exp": "IMC 904 limits unvented room heaters to 40,000 Btu/hr input (and prohibits them in bedrooms/bathrooms). Even where allowed, an outside-air opening is typically required.", "tracks": ["A", "B"], "module": 7 },

  { "id": 74, "art": "IMC 908.3", "q": "A residential cooling tower or evaporative cooler must be:", "opts": ["Listed and installed per manufacturer", "Connected only to potable water without backflow protection", "Located in a bedroom", "Insulated with rigid foam"], "ans": 0, "exp": "IMC 908 — listed, installed per manufacturer, with backflow protection on water supply per the plumbing code. Cooling towers introduce Legionella risk — protection is critical.", "tracks": ["A"], "module": 7 },

  { "id": 75, "art": "IFGC 614", "q": "You're servicing a vented gas fireplace in a Denver home. The required clearances to combustibles are:", "opts": ["Determined by the local AHJ", "Set by IRC Table R1003 alone", "Per the appliance listing and manufacturer's installation instructions", "6 in minimum always"], "ans": 2, "exp": "Listed appliances follow the manufacturer's listed clearances. The code defers to the listing for tested clearances. Field-applied protection requires separate approval.", "tracks": ["A", "B"], "module": 7 },

  { "id": 76, "art": "IMC 901.4", "q": "All appliances must be installed in accordance with:", "opts": ["The local jurisdiction's preference", "The manufacturer's installation instructions and the IMC/IFGC", "Whichever is cheaper", "Industry tradition"], "ans": 1, "exp": "IMC 901.4 / IFGC 301.3 — install per manufacturer's instructions AND the code. Where they conflict, the more restrictive governs. This is foundational.", "tracks": ["A", "B", "G"], "module": 7 },

  { "id": 77, "art": "IMC 907", "q": "You're installing a wall furnace. It must be:", "opts": ["Installed within 12 in of the floor only", "Vented through the wall as listed, with clearances per manufacturer", "Always vertically vented", "Never installed in residential settings"], "ans": 1, "exp": "Wall furnaces are listed for through-wall venting per the manufacturer. Clearances and termination distances follow the listing.", "tracks": ["A", "B"], "module": 7 },

  { "id": 78, "art": "IMC 906", "q": "Floor furnaces serving a residential dwelling must have:", "opts": ["A grille flush with finished floor and access for service from below", "No grille — concealed install", "Combustion air from above only", "No service access"], "ans": 0, "exp": "IMC 906: floor furnaces require a flush grille, listed location (not under or within 6 in of doors/curtains), and service access from below. Largely a legacy appliance but still tested.", "tracks": ["A", "B"], "module": 7 },

  { "id": 79, "art": "IMC 902.4", "q": "A central furnace installed in a residence requires what controls?", "opts": ["A high-limit (temperature) safety only", "Both a high-limit safety and an automatic shutoff on flame failure", "Manual shutoff only", "No safety controls — listed furnaces are pre-tested"], "ans": 1, "exp": "All central furnaces must have high-temperature limit safety AND automatic flame-failure shutoff (gas valve closes if pilot/flame fails). These are listed-equipment requirements baked into the appliance.", "tracks": ["A", "B"], "module": 7 },

  { "id": 80, "art": "IMC Table 403.3.1.1", "q": "You're sizing outdoor air for a new Denver hotel guest room (single occupant). What's the minimum outdoor air rate per ASHRAE 62.1?", "opts": ["3 cfm/person + 0.03 cfm/sq ft", "5 cfm/person + 0.06 cfm/sq ft", "10 cfm/person + 0.12 cfm/sq ft", "20 cfm/person"], "ans": 1, "exp": "Hotel guest rooms: 5 cfm/person + 0.06 cfm/sq ft per IMC Table 403.3.1.1 (default occupancy ~10 per 1,000 sq ft). Effective ~30 cfm/room. This is daily F29 commercial work.", "tracks": ["A"], "module": 8 },

  { "id": 81, "art": "IMC Table 403.3.1.1", "q": "For a 200 sq ft office space with 1 occupant, calculate the minimum outdoor air using ASHRAE 62.1 rates (5 cfm/person + 0.06 cfm/sq ft).", "opts": ["5 cfm", "12 cfm", "17 cfm", "30 cfm"], "ans": 2, "exp": "5 (1 person × 5) + 12 (200 × 0.06) = 17 cfm. Calculation logic: people component + area component, then sum. Mistake to forget the area portion.", "tracks": ["A"], "module": 8 },

  { "id": 82, "art": "IMC Table 403.3.1.1", "q": "For a restaurant dining area, the outdoor air rate is:", "opts": ["5 cfm/person + 0.06 cfm/sq ft", "7.5 cfm/person + 0.18 cfm/sq ft", "10 cfm/person + 0.12 cfm/sq ft", "25 cfm/person"], "ans": 1, "exp": "Restaurant dining: 7.5 cfm/person + 0.18 cfm/sq ft — higher than office because of food odors and dense occupancy. Memorize the dining/office/classroom triad.", "tracks": ["A"], "module": 8 },

  { "id": 83, "art": "IMC Table 403.3.1.1", "q": "Classrooms (ages 5–8) require outdoor air at:", "opts": ["3 cfm/person + 0.03 cfm/sq ft", "5 cfm/person + 0.06 cfm/sq ft", "10 cfm/person + 0.12 cfm/sq ft", "15 cfm/person + 0.18 cfm/sq ft"], "ans": 2, "exp": "K-12 classrooms (ages 5-8): 10 cfm/person + 0.12 cfm/sq ft. Higher than offices because young students are sensitive to CO2 and density is high.", "tracks": ["A"], "module": 8 },

  { "id": 84, "art": "IMC 403.2.1", "q": "Bathroom local exhaust in a dwelling unit must be at least:", "opts": ["25 cfm intermittent OR 10 cfm continuous", "50 cfm intermittent OR 20 cfm continuous", "75 cfm intermittent OR 25 cfm continuous", "100 cfm intermittent OR 50 cfm continuous"], "ans": 1, "exp": "50 cfm intermittent OR 20 cfm continuous — Top 12 Exam Trap #11. Both options are valid; exam can ask for either. Don't pick 25/10 or 100/50.", "tracks": ["A", "B"], "module": 8 },

  { "id": 85, "art": "IMC 403.2.1", "q": "Kitchen local exhaust (residential range hood) must provide at least:", "opts": ["50 cfm intermittent / 20 cfm continuous", "100 cfm intermittent / 25 cfm continuous", "200 cfm intermittent / 50 cfm continuous", "300 cfm intermittent / 100 cfm continuous"], "ans": 1, "exp": "Residential range hood: 100 cfm intermittent OR 25 cfm continuous per IMC Table 403.3.1.1. Distinct from bathroom rates — don't confuse.", "tracks": ["A", "B"], "module": 8 },

  { "id": 86, "art": "IMC 401.4", "q": "An outdoor air intake at a Denver office must be located how far from any contaminant source (loading dock, exhaust, plumbing vent)?", "opts": ["3 ft", "5 ft", "10 ft", "30 ft"], "ans": 2, "exp": "IMC 401.4 — outdoor air intakes shall be located not less than 10 ft horizontally from any hazardous or noxious contaminant source (vents, streets, parking lots, loading docks), OR 3 ft below such sources where within 10 ft of the opening. Hazardous-exhaust outlet separation is the tighter 30 ft rule (IMC 501.3.1). Top 12 exam trap #10.", "tracks": ["A"], "module": 8 },

  { "id": 87, "art": "IMC 501.3.1", "q": "Hazardous exhaust outlet (e.g., paint booth) separation from outdoor air intake:", "opts": ["10 ft", "15 ft", "20 ft", "30 ft"], "ans": 3, "exp": "Hazardous exhaust = 30 ft separation from intake (IMC 501.3.1). Routine intake from contaminants = 10 ft. Knowing both prevents Exam Trap #10 errors.", "tracks": ["A"], "module": 8 },

  { "id": 88, "art": "IMC 404", "q": "Private parking garages require mechanical ventilation at what minimum?", "opts": ["50 cfm continuous", "100 cfm continuous OR 300 cfm intermittent + makeup air", "0.75 cfm/sq ft", "No ventilation required"], "ans": 1, "exp": "Private (residential, ≤3 cars) garage = 100 cfm continuous OR 300 cfm intermittent, both with makeup air. Commercial parking garages use 0.75 cfm/sq ft mechanical or demand-controlled per IMC 404.", "tracks": ["A", "B"], "module": 8 },

  { "id": 89, "art": "IMC 404", "q": "A commercial parking garage in Denver requires mechanical ventilation at:", "opts": ["0.5 cfm/sq ft", "0.75 cfm/sq ft OR demand-controlled per CO/NO2 monitoring", "1.0 cfm/sq ft", "2.0 cfm/sq ft"], "ans": 1, "exp": "Commercial parking garage = 0.75 cfm/sq ft OR demand-controlled (CO sensors). Demand control saves significant fan energy.", "tracks": ["A"], "module": 8 },

  { "id": 90, "art": "IMC 403.5", "q": "A natatorium (indoor swimming pool) requires ventilation primarily designed to:", "opts": ["Cool the pool deck", "Control humidity and chloramines", "Lower CO2 only", "Maintain neutral pressure to the lobby"], "ans": 1, "exp": "Natatorium ventilation controls humidity and indoor chloramine concentration. Dedicated dehumidification + outdoor air mix. Negative pressure to adjacent occupied spaces.", "tracks": ["A"], "module": 8 },

  { "id": 91, "art": "IMC 403.3.1.1", "q": "A patient room in a Denver hospital requires outdoor air per ASHRAE 170 / IMC at:", "opts": ["5 cfm/person", "10 cfm/person", "25 cfm/person", "No outdoor air — sealed envelope"], "ans": 2, "exp": "Patient rooms: 25 cfm/person (and 2 air changes/hour outdoor air per ASHRAE 170). Healthcare is a higher OA standard than commercial.", "tracks": ["A"], "module": 8 },

  { "id": 92, "art": "IMC 403", "q": "A gymnasium requires outdoor air per IMC Table 403.3.1.1 at approximately:", "opts": ["5 cfm/person", "10 cfm/person", "20 cfm/person", "50 cfm/person"], "ans": 2, "exp": "Gym, sport, play area: 20 cfm/person. High activity = high metabolic rate = more dilution needed.", "tracks": ["A"], "module": 8 },

  { "id": 93, "art": "IMC 401.4", "q": "Outdoor intake openings must be protected against weather and:", "opts": ["Painted to match the building", "Provided with insect screens (no smaller than ¼-in mesh) and bird screens", "Sealed shut in winter", "Located at grade only"], "ans": 1, "exp": "IMC 401.5: ¼-in to ½-in mesh screens to keep birds, insects, and debris out without restricting flow. Finer screens clog and fail.", "tracks": ["A"], "module": 8 },

  { "id": 94, "art": "IMC 403.6", "q": "Energy recovery ventilation (ERV) is required for outdoor air systems exceeding a certain capacity in commercial buildings. This is to:", "opts": ["Reduce capital cost", "Recover heat or cooling energy from exhaust air", "Eliminate the need for OA", "Filter particulates"], "ans": 1, "exp": "ERV/HRV transfers sensible (and often latent) energy between exhaust and intake streams. IECC requires ERV above certain cfm thresholds — efficiency code, not IMC base, but commonly tested.", "tracks": ["A"], "module": 8 },

  { "id": 95, "art": "IMC 403.2", "q": "You're sizing OA for a 5,000 sq ft Denver office with 25 occupants. Use 5 cfm/person + 0.06 cfm/sq ft.", "opts": ["125 cfm", "300 cfm", "425 cfm", "550 cfm"], "ans": 2, "exp": "People: 25 × 5 = 125. Area: 5,000 × 0.06 = 300. Total: 425 cfm OA. Always add people + area components — forgetting either underdesigns the system.", "tracks": ["A"], "module": 8 },

  { "id": 96, "art": "IMC 504.8.4.1", "q": "You are designing a residential dryer exhaust run. The dryer is in the basement, the termination is on the second-floor exterior wall. Total straight run = 30 ft, plus three 90° elbows. Is this compliant with the IMC 35-ft rule?", "opts": ["Yes — 30 ft is under 35 ft", "Yes — elbows don't count", "No — total developed length = 30 + (3 × 5) = 45 ft, exceeds 35 ft maximum", "Yes — manufacturer specs override"], "ans": 2, "exp": "IMC 504.8.4.1 — 35 ft TOTAL DEVELOPED LENGTH. Per Table 504.8.4.1 subtract 5 ft per 90° elbow (2.5 ft per 45°). 30 + 15 = 45 ft, over by 10 ft. Need a booster fan, shorter route, or DEDPV-listed system. Manufacturer specs only override when MORE restrictive. Top 12 exam trap #1.", "tracks": ["A", "B"], "module": 9 },

  { "id": 97, "art": "IMC 504.8.4.1", "q": "How much do you subtract from the 35-ft dryer exhaust allowance for each 90° elbow?", "opts": ["2.5 ft", "5 ft", "7.5 ft", "10 ft"], "ans": 1, "exp": "IMC Table 504.8.4.1: 5 ft equivalent length per 90° elbow; 2.5 ft per 45° elbow. Knowing the table lets you calculate quickly — top 12 exam trap #1.", "tracks": ["A", "B"], "module": 9 },

  { "id": 98, "art": "IMC 504.8.2", "q": "Domestic clothes dryer exhaust must:", "opts": ["Be 3-in minimum diameter", "Be 4-in minimum diameter, rigid metal, no screws penetrating the duct", "Use flex duct for entire run", "Terminate in the attic"], "ans": 1, "exp": "IMC 504.8.2 — 4 in min rigid metal (≥0.016 in / 26 ga), smooth interior, NO sheet-metal screws protruding (lint catches on screws). Terminate outdoors, not in attic or crawlspace.", "tracks": ["A", "B"], "module": 9 },

  { "id": 99, "art": "IMC 504.8.3", "q": "A domestic dryer exhaust termination must be located at least how far from any building opening?", "opts": ["12 inches", "2 feet", "3 feet", "10 feet"], "ans": 2, "exp": "IMC 504.8.3 — 3 ft from doors, windows, or other openings to prevent reintroduction of moist lint-laden air. Terminate with a backdraft damper; no screen on the discharge.", "tracks": ["A", "B"], "module": 9 },

  { "id": 100, "art": "IMC 507.12", "q": "You are installing a Type I commercial kitchen hood over a charbroiler. The hood must overhang the cooking surface by at least:", "opts": ["3 inches", "6 inches", "12 inches", "18 inches"], "ans": 1, "exp": "IMC 507.12 — 6 in overhang minimum on all open sides of the cooking surface for canopy hoods. Vertical distance between front lower lip and cooking surface ≤ 4 ft. Critical for plume capture.", "tracks": ["A"], "module": 9 },

  { "id": 101, "art": "IMC 506.3.10", "q": "A horizontal Type I grease duct must have cleanouts at intervals not exceeding:", "opts": ["10 ft", "15 ft", "20 ft", "30 ft"], "ans": 2, "exp": "IMC 506.3.10: cleanouts every 20 ft on horizontal grease duct, plus at changes in direction. Required for grease removal and fire safety.", "tracks": ["A"], "module": 9 },

  { "id": 102, "art": "IMC 506.3.7", "q": "Horizontal Type I (grease) duct must slope toward the hood (or to a grease reservoir) at:", "opts": ["1/16 in/ft", "1/8 in/ft", "1/4 in/ft (2%)", "1/2 in/ft"], "ans": 2, "exp": "1/4 in/ft (2%) toward the hood or grease reservoir. Don't confuse with condensate slope (1/8 in/ft) — these are different IMC sections.", "tracks": ["A"], "module": 9 },

  { "id": 103, "art": "IMC 507.2", "q": "You install a charbroiler. Which kitchen hood type is required?", "opts": ["Type I (grease)", "Type II (heat & moisture)", "Either is acceptable", "No hood — direct outdoor venting only"], "ans": 0, "exp": "Type I = grease-producing appliances (charbroilers, fryers, ranges, griddles). Type II = heat/moisture (dishwashers, steamers, ovens with no grease). A charbroiler is the clearest Type I example.", "tracks": ["A"], "module": 9 },

  { "id": 104, "art": "IMC 506.3.11", "q": "Type I grease duct clearance to combustibles unless field-applied protection is used:", "opts": ["3 inches", "6 inches", "12 inches", "18 inches"], "ans": 3, "exp": "IMC 506.3.11: 18 in clearance to combustibles for grease duct. Field-applied UL-listed protection (e.g., wrap, enclosure) can reduce this. Major fire-prevention rule.", "tracks": ["A"], "module": 9 },

  { "id": 105, "art": "IMC 505.2", "q": "Residential range hood exhaust exceeding 400 cfm requires:", "opts": ["A second hood", "Mechanical makeup air sized for the exhaust flow", "A larger gas line", "A separate circuit"], "ans": 1, "exp": "IMC 505.2: range hoods over 400 cfm require mechanical makeup air. High-cfm hoods can backdraft furnaces and water heaters — makeup air is a code safety rule, not optional.", "tracks": ["A", "B"], "module": 9 },

  { "id": 106, "art": "IMC 501.3.1", "q": "Hazardous exhaust (paint booths, lab fume hoods, etc.) discharge must be located how far from any outdoor air intake?", "opts": ["10 ft", "20 ft", "30 ft", "60 ft"], "ans": 2, "exp": "IMC 501.3.1: 30 ft separation for hazardous exhaust. Routine kitchen and dryer exhaust = 10 ft. Don't confuse.", "tracks": ["A"], "module": 9 },

  { "id": 107, "art": "IMC 504.4", "q": "Bathroom exhaust may terminate in:", "opts": ["The attic", "The crawlspace", "Outdoors only", "The garage"], "ans": 2, "exp": "All exhaust (bathroom, dryer, kitchen) must terminate outdoors — never into attics, crawlspaces, walls, or garages. Moisture/odor in concealed spaces = mold/rot.", "tracks": ["A", "B"], "module": 9 },

  { "id": 108, "art": "IMC 506.3", "q": "Type I grease duct construction must be:", "opts": ["Galvanized steel, 26 ga", "Continuously welded carbon steel (16 ga) OR stainless steel (18 ga)", "Aluminum", "PVC"], "ans": 1, "exp": "IMC 506.3: continuously welded 16 ga black/carbon steel or 18 ga stainless. No mechanical joints — welds only, to prevent grease leakage and fire.", "tracks": ["A"], "module": 9 },

  { "id": 109, "art": "IMC 506.3.11.1", "q": "Type I grease duct fire-rated enclosure ('grease shaft') requirements include:", "opts": ["1-hour rated shaft for 3 stories or less", "Min 1-hour rated (less than 4 stories), 2-hour rated (4 stories or more) shaft enclosure", "No enclosure ever", "Sheetrock with no rating"], "ans": 1, "exp": "IMC 506.3.11.1: less than 4 stories = 1-hr enclosure; 4 stories or more = 2-hr. Grease ducts in high-rise hotels = 2-hr shaft. Critical for Class A hotel work.", "tracks": ["A"], "module": 9 },

  { "id": 110, "art": "IMC 510", "q": "Hazardous exhaust ducts (e.g., laboratory fume hood) must be constructed of:", "opts": ["Galvanized steel", "Material compatible with the contaminant; often stainless or PVC", "Standard rectangular duct", "Flex duct"], "ans": 1, "exp": "IMC 510: material compatibility with the substance exhausted is paramount. Stainless or coated for corrosives; FRP/PVC for some chemicals; metal for flammable vapors (with bonding/grounding).", "tracks": ["A"], "module": 9 },

  { "id": 111, "art": "IMC 506.4", "q": "Type I hood exhaust duct must be a separate system from:", "opts": ["The HVAC return", "Any other type of exhaust system (including Type II)", "Plumbing vents", "Combustion air"], "ans": 1, "exp": "IMC 506.3.3: Type I (grease) exhaust must be independent of all other exhaust systems. No common ducting with Type II or general exhaust. Fire-safety isolation.", "tracks": ["A"], "module": 9 },

  { "id": 112, "art": "IMC 603.4", "q": "Maximum support spacing for round metal duct (per SMACNA):", "opts": ["4 ft", "6 ft", "10 ft", "12 ft"], "ans": 2, "exp": "Round metal duct: 10 ft maximum support spacing. Rectangular: 8 ft. Strap hangers per SMACNA. Sagging duct kills airflow and causes joint failure.", "tracks": ["A", "B"], "module": 10 },

  { "id": 113, "art": "IMC 603.6", "q": "Flexible duct used to connect ductwork to a register may extend a maximum of:", "opts": ["3 ft", "5 ft", "8 ft", "10 ft"], "ans": 1, "exp": "IMC 603.6: flex duct ≤ 5 ft for connecting hard duct (longer runs allowed for terminal connections per the listing, but 5 ft is the general limit). Flex adds significant static pressure.", "tracks": ["A", "B"], "module": 10 },

  { "id": 114, "art": "IMC 604.1", "q": "Duct insulation R-value in Denver (climate zone 5B) supply ducts in unconditioned spaces is typically required at:", "opts": ["R-2", "R-4", "R-6 to R-8 (per IECC)", "R-19"], "ans": 2, "exp": "IECC for zone 5B: R-6 supply, R-3 return in unconditioned spaces (R-8 supply for very cold zones). Denver = zone 5B. Use IECC tables in conjunction with IMC.", "tracks": ["A", "B"], "module": 10 },

  { "id": 115, "art": "IMC 602.2.1", "q": "Combustible materials within a plenum are:", "opts": ["Always permitted", "Permitted only if listed for plenum use (per Section 602.2.1) — no exposed combustibles", "Permitted if behind sheet metal", "Never permitted under any condition"], "ans": 1, "exp": "IMC 602.2: only listed/plenum-rated materials in plenums (e.g., plenum-rated wiring, ICC-listed plumbing). Exposed PVC, foam, etc. = code violation.", "tracks": ["A", "B"], "module": 10 },

  { "id": 116, "art": "IMC 601.5", "q": "Return air is NOT permitted from which of the following?", "opts": ["Kitchen, bathroom, closet (other than laundry), garage, mechanical room", "Living rooms", "Bedrooms", "Offices"], "ans": 0, "exp": "IMC 601.5 prohibits return air from kitchens, bathrooms, closets (except laundry), garages, and mechanical rooms — contamination/CO/odor concerns.", "tracks": ["A", "B"], "module": 10 },

  { "id": 117, "art": "IMC 602.3", "q": "An underground duct must be:", "opts": ["Buried in sand only", "Encased in at least 2 in of concrete or other approved corrosion-resistant material", "Made of PVC always", "At least 36 in below grade"], "ans": 1, "exp": "IMC 602.3: 2-in concrete encasement (or listed corrosion-resistant material). Must be sloped to drain, low-point cleanout. Underground duct is high-effort but sometimes unavoidable.", "tracks": ["A", "B"], "module": 10 },

  { "id": 118, "art": "IMC 603.1", "q": "Sheet metal duct gauge and SMACNA construction standards depend on:", "opts": ["Cost", "Static pressure class, size, and shape", "Aesthetic preference", "Building occupancy only"], "ans": 1, "exp": "SMACNA duct construction tables by pressure class (½, 1, 2, 3, 4, 6, 10 in wg), shape, and largest dimension. Higher pressure = thicker gauge + more reinforcement.", "tracks": ["A"], "module": 10 },

  { "id": 119, "art": "IMC 603", "q": "Approved duct materials include:", "opts": ["Galvanized steel, aluminum, factory-made UL 181 listed duct, rigid fibrous glass, gypsum", "PVC pipe", "Wood", "Drywall in non-rated chases only"], "ans": 0, "exp": "IMC 603: listed materials only. Galvanized steel is the dominant material; aluminum, UL 181 factory duct (rigid or flex), fibrous glass duct, and gypsum (limited) are permitted. PVC is plumbing, not duct.", "tracks": ["A", "B"], "module": 10 },

  { "id": 120, "art": "IMC 603.10", "q": "Volume dampers must be:", "opts": ["Located concealed in walls", "Accessible for adjustment after installation", "Manual only — never motorized", "Spring-loaded closed"], "ans": 1, "exp": "Volume dampers must remain accessible for balancing. Buried in finished walls = code violation. Provide access panels.", "tracks": ["A", "B"], "module": 10 },

  { "id": 121, "art": "IMC 607", "q": "Fire dampers are required where ducts penetrate:", "opts": ["Any wall", "Fire-rated walls, floors, and shaft enclosures per IBC", "Only exterior walls", "Ceiling assemblies only"], "ans": 1, "exp": "IMC 607 + IBC 717: fire/smoke dampers wherever rated assemblies are penetrated. Class A inspections check these heavily.", "tracks": ["A"], "module": 10 },

  { "id": 122, "art": "IMC 601.3", "q": "Combustion air ducts and return air ducts must:", "opts": ["Always be combined for efficiency", "Be separate systems — combustion air cannot mix with return air", "Use the same plenum", "Use shared registers"], "ans": 1, "exp": "IMC 601.3 / IFGC 304: combustion air must be a separate, dedicated supply. Mixing with return air can starve appliances of combustion air and create CO hazards.", "tracks": ["A", "B"], "module": 10 },

  { "id": 123, "art": "IMC 603.2", "q": "A 12 in × 24 in rectangular duct in a 1-in wg system requires reinforcement per:", "opts": ["NEC tables", "SMACNA HVAC Duct Construction Standards", "ASHRAE Handbook only", "Manufacturer choice"], "ans": 1, "exp": "SMACNA HVAC Duct Construction Standards — Metal & Flexible is THE reference. IMC adopts it by reference. Required for sizing gauge, reinforcement, and joint spacing.", "tracks": ["A"], "module": 10 },

  { "id": 124, "art": "IMC 604", "q": "Duct sealing per IMC 603.9 requires:", "opts": ["Tape only", "Listed sealants, mastics, or gasketed joints to meet a leakage class (typically Class A or B)", "No sealing required", "Welding all joints"], "ans": 1, "exp": "Duct sealing per IMC 603.9 / IECC: mastic, listed tape, gaskets to meet leakage class. Energy code drives this — leaky duct = wasted conditioned air.", "tracks": ["A", "B"], "module": 10 },

  { "id": 125, "art": "IMC 603.4", "q": "Maximum support spacing for rectangular metal duct:", "opts": ["4 ft", "6 ft", "8 ft", "10 ft"], "ans": 2, "exp": "Rectangular = 8 ft max support spacing; round = 10 ft. Heavier rectangular duct needs closer supports. Both are testable.", "tracks": ["A", "B"], "module": 10 },

  { "id": 126, "art": "IMC 1009", "q": "All automatically fired steam and hot water boilers must be equipped with:", "opts": ["A condensate pump", "A low-water cutoff", "An expansion tank only", "A magnetic dirt separator"], "ans": 1, "exp": "IMC 1009: low-water cutoff required on every automatically fired boiler. Boiler running dry = catastrophic failure. ASME-required safety device.", "tracks": ["A"], "module": 11 },

  { "id": 127, "art": "IMC 1006", "q": "Between a boiler and its pressure relief valve, you may install:", "opts": ["A shutoff valve", "Nothing — no valves between boiler and relief", "A pressure gauge tee", "A drain"], "ans": 1, "exp": "NO VALVES between boiler and relief. A closed valve = no relief path = explosion. ASME boiler-and-pressure-vessel safety axiom.", "tracks": ["A"], "module": 11 },

  { "id": 128, "art": "IMC 1004", "q": "A pressure vessel for a hot water heating boiler must bear the:", "opts": ["UL listing only", "ASME stamp (and National Board registration)", "NFPA stamp", "Manufacturer signature"], "ans": 1, "exp": "ASME Boiler & Pressure Vessel Code stamp required + National Board registration (NB number). The stamp is the regulatory mark — verify on every install.", "tracks": ["A"], "module": 11 },

  { "id": 129, "art": "IMC 1006.5", "q": "The discharge from a boiler safety relief valve must:", "opts": ["Discharge to atmosphere through a vertical pipe with no valves, terminating at a safe location", "Discharge into the boiler return", "Be capped", "Connect to the floor drain through a P-trap"], "ans": 0, "exp": "Relief discharge = open, no valves, safe location, full size or larger. Vertical to atmosphere or floor drain (air-gapped) — never plumbed into anything pressurized.", "tracks": ["A"], "module": 11 },

  { "id": 130, "art": "IMC 1004.2", "q": "Working clearance in front of a boiler should be at least:", "opts": ["18 in", "24 in", "36 in", "Per manufacturer's listing and IMC 306"], "ans": 3, "exp": "Per the manufacturer's listing first; default IMC 306 clearance is 30 in. Many boilers require more — tube pull length matters for fire-tube boilers. Always check the manual.", "tracks": ["A"], "module": 11 },

  { "id": 131, "art": "IMC 1004", "q": "A high-pressure steam boiler is one operating above:", "opts": ["10 psi", "15 psi", "30 psi", "100 psi"], "ans": 1, "exp": "ASME definition: steam boiler > 15 psi = high pressure (requires different operator licensing in many jurisdictions). Below 15 psi = low pressure.", "tracks": ["A"], "module": 11 },

  { "id": 132, "art": "IMC 1005", "q": "Boiler room combustion air requirements follow:", "opts": ["IMC Chapter 4", "IFGC Chapter 3 (304)", "NFPA 90A", "IBC Chapter 7"], "ans": 1, "exp": "All fuel-fired equipment combustion air = IFGC 304, regardless of whether it's a furnace, water heater, or boiler. Same calculations apply.", "tracks": ["A"], "module": 11 },

  { "id": 133, "art": "IMC 1003", "q": "A hot water heating boiler with a working pressure rating of 30 psi must have:", "opts": ["A relief valve set no higher than the working pressure (30 psi)", "A relief valve set 50% above working pressure", "No relief valve", "A pressure gauge only"], "ans": 0, "exp": "Relief valve must be set at or below the vessel's rated working pressure. A higher setting defeats the purpose of relief. Listed ASME-stamped relief valve required.", "tracks": ["A"], "module": 11 },

  { "id": 134, "art": "IMC 1010", "q": "An expansion tank is required on:", "opts": ["Steam systems only", "Closed hot-water systems to absorb thermal expansion", "All systems above 100 °F", "Boilers in Colorado only"], "ans": 1, "exp": "Closed hot-water systems require an expansion tank (diaphragm or bladder type modern). Without one, thermal expansion opens the relief valve every cycle.", "tracks": ["A"], "module": 11 },

  { "id": 135, "art": "IMC 1001.2", "q": "Boiler permits and inspections in Denver are administered by:", "opts": ["EPA", "Colorado Division of Oil & Public Safety (state) plus Denver CPD", "NFPA", "Manufacturer's rep"], "ans": 1, "exp": "Colorado boiler inspection program (under Division of Oil and Public Safety) plus Denver CPD permits. Larger pressure vessels also need state Boiler Inspection certificates.", "tracks": ["A"], "module": 11 },

  { "id": 136, "art": "IMC 1105.6", "q": "You're designing a Denver hotel chiller plant using R-134a. The machinery room emergency shutoff switch must be located:", "opts": ["Inside the room, accessible", "Outside the room, at the principal entrance", "On the chiller itself only", "On the building main electrical panel"], "ans": 1, "exp": "Top 12 Exam Trap #12: emergency switch OUTSIDE the machinery room at the principal entrance. Switch inside = code violation; technicians can't safely shut down in an emergency. Always outside, always accessible.", "tracks": ["A", "E"], "module": 12 },

  { "id": 137, "art": "IMC 1105.3", "q": "A refrigerant detector in a machinery room must be installed:", "opts": ["At the ceiling", "At the floor", "At a height appropriate for the refrigerant density (typically low for heavy refrigerants)", "Outside the room"], "ans": 2, "exp": "Detector location follows refrigerant density. Most common refrigerants (R-410A, R-134a) are heavier than air → low. Ammonia (R-717) is lighter → high. Per ASHRAE 15 and IMC 1105.3.", "tracks": ["A", "E"], "module": 12 },

  { "id": 138, "art": "IMC Table 1103.1", "q": "R-410A is classified as:", "opts": ["A1 (lowest toxicity, no flame propagation)", "A2L (mildly flammable)", "B1 (higher toxicity)", "B2 (toxic + flammable)"], "ans": 0, "exp": "R-410A = A1 (low toxicity, no flame propagation, A-class safest). R-32 and R-454B (its replacements) are A2L. R-123 is B1. Know the safety classification grid.", "tracks": ["A", "E"], "module": 12 },

  { "id": 139, "art": "IMC Table 1103.1", "q": "R-32 (modern A2L replacement refrigerant) is classified as:", "opts": ["A1", "A2L (mildly flammable)", "B1", "B2L"], "ans": 1, "exp": "R-32 = A2L: mildly flammable, low toxicity. A2L refrigerants are taking over as low-GWP replacements (R-32, R-454B, R-1234yf). Require updated machinery room rules per IMC 2018+.", "tracks": ["A", "E"], "module": 12 },

  { "id": 140, "art": "IMC 1105.6.3", "q": "A Denver hotel chiller plant has a refrigerant machinery room. Which statement correctly describes the IMC 1105.6.3 ventilation requirements?", "opts": ["20 cfm/person continuous in all cases", "Normal: 20 cfm/person OR 0.5 cfm/sq ft, whichever greater. Emergency: Q = 100·√G cfm, where G = lb of refrigerant in the largest system", "30 cfm/person OR calculated per refrigerant quantity, whichever greater", "0.35 cfm per 1,000 Btu/hr"], "ans": 1, "exp": "IMC 1105.6.3.1 (normal, occupied): the GREATER of 20 cfm/person OR 0.5 cfm/sq ft. IMC 1105.6.3.2 (emergency, on detection): Q = 100·√G cfm (G in lb of refrigerant in largest system) — no per-person component. The '30 cfm/person' value is a common student error; it does not appear in IMC Ch.11 or ASHRAE 15.", "tracks": ["A", "E"], "module": 12 },

  { "id": 141, "art": "ASHRAE 15", "q": "A direct system using R-22 in a public assembly (Group A1) is limited to what charge per IMC Table 1103.1?", "opts": ["No limit", "Charge limits per ASHRAE 15 by refrigerant class and occupancy", "100 lb maximum always", "500 lb maximum always"], "ans": 1, "exp": "IMC 1103 + ASHRAE 15 set charge limits by occupancy class and refrigerant safety class. A1 in public spaces gets higher limits than B refrigerants. Lookup table on the exam.", "tracks": ["A"], "module": 12 },

  { "id": 142, "art": "IMC 1105.7", "q": "Refrigerant relief discharge from a pressure-relief valve must terminate:", "opts": ["Inside the machinery room", "Outdoors, at least 20 ft from any building opening", "At the floor drain", "To the suction line"], "ans": 1, "exp": "IMC 1105.7: outdoors, ≥20 ft from openings, ≥7.25 ft above adjoining grade, and away from intakes. Discharging inside the room would gas the technicians.", "tracks": ["A", "E"], "module": 12 },

  { "id": 143, "art": "IMC 1106.1", "q": "Refrigerant piping must be sized and installed per:", "opts": ["NFPA 13", "ASHRAE 15 and the appliance listing", "NEC", "IBC Chapter 10"], "ans": 1, "exp": "ASHRAE 15 governs refrigerant piping safety, plus the equipment manufacturer's listed pipe sizing/design. Pipe failure = mass refrigerant release = code violation.", "tracks": ["A"], "module": 12 },

  { "id": 144, "art": "IMC 1104", "q": "A refrigerant machinery room must be:", "opts": ["Open to the building", "Separated from other rooms by tight construction with no openings except for ventilation, refrigerant piping, and required egress", "Used for HVAC equipment only when convenient", "Combined with the boiler room"], "ans": 1, "exp": "IMC 1104.2.1: tight separation, no openings into occupied spaces (except mechanical penetrations sealed), self-closing tight-fitting door, no refrigerant detection wiring through walls without seal.", "tracks": ["A", "E"], "module": 12 },

  { "id": 145, "art": "IMC 1106", "q": "Refrigerant pipe joints in occupied areas must be:", "opts": ["Soldered with lead solder", "Brazed (high-temp), not soldered", "Glued with PVC primer", "Threaded only"], "ans": 1, "exp": "Refrigerant lines require brazed joints (silver-bearing, high temp). Soft solder fails at refrigerant operating temperatures. Threaded joints leak under refrigerant pressure.", "tracks": ["A", "E"], "module": 12 },

  { "id": 146, "art": "IMC 1103", "q": "R-744 (CO2) refrigerant systems are classified as:", "opts": ["A1 — lowest hazard", "B1", "A2L", "A3"], "ans": 0, "exp": "CO2 (R-744) = A1: no toxicity (in refrigerant doses), no flammability. But operates at very high pressures (trans-critical >1,000 psi) and asphyxiation risk if leaks fill space.", "tracks": ["A", "E"], "module": 12 },

  { "id": 147, "art": "IMC 1105", "q": "A walk-in refrigerator using R-290 (propane) is classified as:", "opts": ["A1", "A2L", "A3 (highly flammable)", "B1"], "ans": 2, "exp": "R-290 = A3: low toxicity, highly flammable. Charge limits are tight, machinery rooms typically not allowed, dedicated leak detection required. Small commercial units only.", "tracks": ["A", "E"], "module": 12 },

  { "id": 148, "art": "IMC 1105", "q": "Ammonia (R-717) refrigerant machinery rooms require:", "opts": ["Same rules as R-410A", "Special construction (vapor barriers, eye wash, dedicated emergency vent, leak detector at HIGH point)", "No special treatment", "Open ventilation through windows"], "ans": 1, "exp": "NH3 = B2L (toxic + mildly flammable, lighter than air). Industrial-grade rooms with eye-wash, alarms, ammonia-rated detector at HIGH point. Very different from halocarbon design.", "tracks": ["A", "E"], "module": 12 },

  { "id": 149, "art": "IMC 1105.4", "q": "Refrigerant machinery room ventilation that runs continuously is sized to:", "opts": ["Pull in just enough OA for one person", "Move 0.5 cfm per sq ft of refrigerated space", "Per ASHRAE 15 calculation, with emergency mode boost", "Match outdoor air rates for offices"], "ans": 2, "exp": "ASHRAE 15 gives normal + emergency cfm. Normal continuous ventilation is moderate; emergency ventilation activates on refrigerant detection and pulls full design cfm.", "tracks": ["A", "E"], "module": 12 },

  { "id": 150, "art": "IMC 1209", "q": "An expansion tank in a closed-loop hot water system serves to:", "opts": ["Filter sediment", "Absorb thermal expansion of fluid and maintain system pressure", "Boost circulation", "Mix domestic water with heating water"], "ans": 1, "exp": "IMC 1209 expansion tank — diaphragm or bladder — accommodates ~4% volumetric expansion as water heats from 60°F to 180°F. Without it, relief valves dump and weep.", "tracks": ["A"], "module": 13 },

  { "id": 151, "art": "IMC 1208", "q": "Hydronic pipe insulation R-value in unconditioned spaces (Denver, zone 5B) for 1-1/4-in heating water pipe is typically:", "opts": ["R-2", "R-3", "R-4 (per IECC C403)", "R-19"], "ans": 2, "exp": "IECC 2018 Table C403.10.3 — typical 1-1/2 in pipe at 200°F = 1.5 in insulation (~R-4). Pipe size and operating temp drive the table.", "tracks": ["A"], "module": 13 },

  { "id": 152, "art": "IMC 1206", "q": "A hot water heating system uses what valve for individual zone control?", "opts": ["Three-way control valve", "Zone valve (motorized 2-way or 3-way) tied to a thermostat", "Manual ball valve", "Solenoid only"], "ans": 1, "exp": "Motorized zone valves with low-voltage transformers and thermostat control. Common in residential and small commercial — F29 expects you to recognize the layout.", "tracks": ["A"], "module": 13 },

  { "id": 153, "art": "IMC 1207", "q": "An air separator in a hydronic system is installed:", "opts": ["After the boiler return", "On the suction side of the pump, near the expansion tank", "On the relief discharge", "On the makeup water line only"], "ans": 1, "exp": "Air separator at the highest-temp, lowest-pressure point — typically just downstream of the boiler, on the suction side of the pump, tied to the expansion tank. Removes entrained air.", "tracks": ["A"], "module": 13 },

  { "id": 154, "art": "IMC 1203", "q": "Approved materials for hydronic piping include:", "opts": ["Copper, steel, brass, PEX, CPVC (per listing), PE-RT", "PVC (Schedule 40)", "Galvanized steel (high temp)", "Aluminum tubing"], "ans": 0, "exp": "IMC 1202 lists copper, black/stainless steel, brass, PEX (with O2 barrier for ferrous boilers), CPVC, PE-RT. PVC is NOT rated for the temperatures (max ~140°F).", "tracks": ["A"], "module": 13 },

  { "id": 155, "art": "IMC 1210", "q": "Backflow protection on hydronic system makeup water requires:", "opts": ["No protection — closed loop", "RP (reduced pressure) backflow preventer or per local plumbing code", "Single check valve only", "Air gap only"], "ans": 1, "exp": "Hydronic systems often contain glycol or chemical treatment — DOH-classified high hazard → RP backflow preventer required on makeup water connection to potable supply.", "tracks": ["A"], "module": 13 },

  { "id": 156, "art": "IMC 1204", "q": "In-floor radiant tubing typically uses:", "opts": ["Copper, soldered", "PEX (often PEX-AL-PEX) per manufacturer", "Black iron pipe", "CPVC sleeved"], "ans": 1, "exp": "PEX (often with aluminum core in PEX-AL-PEX) is standard for radiant slab installs — flexibility, no joints in slab, oxygen barrier required for ferrous boilers.", "tracks": ["A"], "module": 13 },

  { "id": 157, "art": "IMC 1208", "q": "A pressure relief valve on a hot water heating boiler is set at:", "opts": ["The boiler MAWP or less, never above", "150% of operating pressure", "30 psi for all boilers", "Per the discharge piping size"], "ans": 0, "exp": "Relief set at or below the boiler's Maximum Allowable Working Pressure (MAWP). Listed ASME-stamped relief valve. Discharge piping size matches the relief outlet — never reduced.", "tracks": ["A"], "module": 13 },

  { "id": 158, "art": "IMC 1206", "q": "In-line circulator pumps in a hydronic system should be sized to overcome:", "opts": ["Static system pressure", "System friction loss at design flow (not static pressure)", "Atmospheric pressure", "Pump suction pressure"], "ans": 1, "exp": "Closed-loop pumps work against friction (head), not static (the column re-balances on the return). Sizing by static is a classic novice mistake.", "tracks": ["A"], "module": 13 },

  { "id": 159, "art": "IMC 1208", "q": "A hydronic system in a Denver building loses 10 psi static between floors. The expansion tank precharge should be set to:", "opts": ["0 psi", "System fill pressure at the tank location", "100 psi", "Whatever the manufacturer ships"], "ans": 1, "exp": "Expansion tank precharge = system fill pressure at the tank location (typically at the air separator / pump inlet). Pre-charge too low → tank floods; too high → relief lifts on heat.", "tracks": ["A"], "module": 13 },

  { "id": 160, "art": "IMC 401.4 / IRC M1505", "q": "You're installing HVAC in a Denver duplex. Class B scope applies. The A/C system is limited to:", "opts": ["3 tons", "5 tons", "7 tons", "10 tons"], "ans": 1, "exp": "Class B cap: A/C ≤5 tons (60,000 Btu/hr). Larger systems require Class A. Hard limit.", "tracks": ["B"], "module": 14 },

  { "id": 161, "art": "Denver CPD Class B", "q": "A Class B mechanical contractor can install a water heater up to:", "opts": ["75 MBtu input", "100 MBtu input", "150 MBtu input", "199 MBtu input"], "ans": 1, "exp": "Class B residential water heater max = 100 MBtu input. Tankless water heaters at 199 MBtu (common) require Class A or a Gas Service Contractor.", "tracks": ["B", "G"], "module": 14 },

  { "id": 162, "art": "IRC M1411", "q": "A residential central A/C condensate drain in a Denver attic must include:", "opts": ["Primary drain only", "Primary drain + auxiliary pan with drain or water-level shutoff", "No drain — gravity to soil", "Pump only"], "ans": 1, "exp": "IRC M1411 / IMC 307.2.3: primary + secondary protection (aux pan with drain OR float switch). Attic location = water damage risk = code mandates the redundancy.", "tracks": ["B"], "module": 14 },

  { "id": 163, "art": "IRC M1305", "q": "Residential furnace working clearance must include:", "opts": ["18 in front", "30 in × 30 in × 78 in front", "36 in × 36 in front", "48 in front"], "ans": 1, "exp": "IRC M1305 mirrors IMC 306.1: 30 in wide × 30 in deep × 78 in high working space in front of equipment.", "tracks": ["B"], "module": 14 },

  { "id": 164, "art": "IRC M1502.4", "q": "A residential clothes dryer exhaust duct may not exceed:", "opts": ["25 ft total developed length", "35 ft total developed length (subtract 5 ft per 90°)", "50 ft total", "No limit"], "ans": 1, "exp": "35 ft TDL — same as IMC 504.6.1. Top 12 Exam Trap #1. Subtract 5 ft per 90° elbow, 2.5 ft per 45°. Manufacturer override if MORE restrictive.", "tracks": ["B"], "module": 14 },

  { "id": 165, "art": "IRC M1411.4", "q": "In Denver climate zone 5B, a residential heat pump must:", "opts": ["Have a defrost cycle and be sized for both heating and cooling design loads", "Be sized for cooling only — heat strips do the rest", "Be installed only with backup gas furnace", "Not be used"], "ans": 0, "exp": "Heat pumps in Denver work well — must include defrost cycle and be sized for both heat and cool loads (Manual J). Backup heat (strip or dual fuel) typical for sub-zero events. Auxiliary heat lockout per Denver energy code.", "tracks": ["B"], "module": 14 },

  { "id": 166, "art": "IRC M1411", "q": "Residential gas furnace combustion air is governed by:", "opts": ["IMC Ch.4", "IFGC 304", "NEC", "IRC P3001"], "ans": 1, "exp": "Combustion air = IFGC 304, even for residential. The IRC mechanical chapter cross-references IFGC for fuel-gas appliances.", "tracks": ["B"], "module": 14 },

  { "id": 167, "art": "IRC M1411", "q": "A 2-ton residential A/C system pulls about how many cfm of supply air?", "opts": ["200 cfm", "400 cfm", "800 cfm (400 cfm/ton rule of thumb)", "1,200 cfm"], "ans": 2, "exp": "Industry rule of thumb: 400 cfm/ton supply airflow (cooling). 2 tons × 400 = 800 cfm. Critical for duct sizing — Manual D uses this as a starting point.", "tracks": ["B"], "module": 14 },

  { "id": 168, "art": "IRC M1305", "q": "A residential furnace closet door must be:", "opts": ["At least 24 in wide", "Sized to provide the required working clearance, with no overlap into the clearance zone", "Solid wood only", "Optional"], "ans": 1, "exp": "Door cannot encroach into the required working space. Practical width: usually 30 in min for full access. Always check door swing.", "tracks": ["B"], "module": 14 },

  { "id": 169, "art": "IRC G2407.6.1", "q": "A residential 80,000 Btu/hr furnace and 40,000 Btu/hr water heater share a Denver mechanical room. Total = 120,000 Btu/hr. Using the two-opening OUTDOOR air method (direct outdoors / vertical duct), each opening must be:", "opts": ["30 sq in", "100 sq in (minimum floor)", "120 sq in", "240 sq in"], "ans": 1, "exp": "IRC G2407.6.1 (= IFGC 304.6.1) outdoor two-opening (direct or vertical duct) = 1 sq in per 4,000 Btu/hr per opening: 120,000 ÷ 4,000 = 30 sq in calculated, which is below the 100 sq in minimum-area floor, so 100 sq in each governs. Horizontal duct = 1 sq in / 2,000 Btu/hr per opening. Indoor combining-spaces (different rule) = 1 sq in / 1,000 Btu/hr. Top exam trap #2.", "tracks": ["B", "G"], "module": 14 },

  { "id": 170, "art": "IRC M1502", "q": "A residential booster fan for clothes dryer exhaust is required when:", "opts": ["The duct is longer than 25 ft", "The total developed length exceeds the manufacturer's max", "The duct is plastic", "The dryer is gas"], "ans": 1, "exp": "Booster fan when total developed length exceeds the dryer manufacturer's max. Must be listed and rated for dryer exhaust (handles lint). Plastic duct is never allowed.", "tracks": ["B"], "module": 14 },

  { "id": 171, "art": "IRC M1411.6", "q": "A residential gas water heater installed in a Denver garage:", "opts": ["Must have ignition source ≥18 in above floor", "Is prohibited in garages", "Requires no special elevation", "Must be electric only"], "ans": 0, "exp": "IRC M1307.3 / IFGC 305.3: ignition source 18 in above garage floor for gasoline vapor protection. Same as commercial. Top tested number.", "tracks": ["B"], "module": 14 },

  { "id": 172, "art": "IPC 504 / IFGC 624", "q": "A residential gas water heater requires which two safety devices on the tank?", "opts": ["Pressure relief only", "Temperature & Pressure (T&P) relief valve combined", "T&P relief and a sediment trap", "Sacrificial anode and T&P"], "ans": 1, "exp": "All storage water heaters require a T&P valve (combined temperature + pressure). Sediment trap is on the gas line (different rule). Sacrificial anode is corrosion protection, not safety.", "tracks": ["A", "B", "G"], "module": 15 },

  { "id": 173, "art": "IPC 504.6", "q": "T&P relief valve discharge piping requirements include:", "opts": ["Trapped, with a P-trap", "Full size, sloped down, terminating with air gap to a safe location ≤6 in above floor", "Reduced size", "Capped"], "ans": 1, "exp": "Discharge piping: full size of valve outlet (no reductions), no traps, sloped down, terminates with air gap above a drain/floor 6-24 in from finished floor. Never threaded for a cap.", "tracks": ["A", "B", "G"], "module": 15 },

  { "id": 174, "art": "IFGC 624.1.1", "q": "You're installing a tankless gas water heater rated 199 MBtu input in a Denver residence. Which Denver certificate covers this scope?", "opts": ["Class B H&V", "Class A H&V or Gas Service Contractor", "Plumbing C-36", "No license needed"], "ans": 1, "exp": "Class B is capped at 100 MBtu water heaters. 199 MBtu requires Class A H&V or Gas Service Contractor (F33). This is the classic tankless trap.", "tracks": ["A", "G"], "module": 15 },

  { "id": 175, "art": "IPC 501.6", "q": "A heat pump water heater installed indoors must:", "opts": ["Be vented to outdoors", "Be in a space large enough to maintain operation OR ducted to draw/exhaust outside", "Have a gas connection", "Be on a concrete slab"], "ans": 1, "exp": "HPWH removes heat from surrounding air. Manufacturer specifies minimum room volume (typ 700-1000 ft³) or allows ducting in/out. Closets need ducting kits.", "tracks": ["A", "B"], "module": 15 },

  { "id": 176, "art": "IFGC 624.2", "q": "A gas water heater located in a garage must have ignition source elevated:", "opts": ["6 in above floor", "12 in above floor", "18 in above floor", "No requirement"], "ans": 2, "exp": "IFGC 305.3: 18 in above garage floor — same as furnace rule. Listed FVIR (flammable vapor ignition resistant) heaters are still typically installed elevated.", "tracks": ["A", "B", "G"], "module": 15 },

  { "id": 177, "art": "IECC C404.2", "q": "Hot water pipe insulation in commercial buildings is required for:", "opts": ["All hot water lines, any size", "Hot water lines ≥3/4 in nominal size and recirculation lines", "Cold water lines only", "Drain lines only"], "ans": 1, "exp": "IECC C404.2: insulation on hot water lines ≥¾ in and any recirculation line. Standby loss is major energy waste. Denver enforces IECC.", "tracks": ["A"], "module": 15 },

  { "id": 178, "art": "IPC 504", "q": "A water heater pan is required:", "opts": ["Always", "When the water heater is in a location where leakage would damage the building (e.g., attic, upper-floor closet)", "Only on electric water heaters", "Only on gas water heaters"], "ans": 1, "exp": "IPC 504.7: pan required where leakage could cause damage (attic, upstairs closet, finished basement above another finished space). Pan drains to a safe location.", "tracks": ["A", "B"], "module": 15 },

  { "id": 179, "art": "IFGC 624", "q": "The flue collar on a gas storage water heater terminates into:", "opts": ["Open air in the closet", "A draft hood (Category I) connecting to a Type B vent", "Direct connection to the chimney with no draft hood", "An exhaust fan"], "ans": 1, "exp": "Atmospheric storage water heater = Category I → draft hood → Type B (or B-W) vent → chimney/roof. Condensing tankless units skip the draft hood (Category IV, PVC vent).", "tracks": ["A", "B", "G"], "module": 15 },

  { "id": 180, "art": "IPC 501.6", "q": "Maximum water heater temperature setting for residential use is typically:", "opts": ["110°F", "120°F (anti-scald)", "140°F", "180°F"], "ans": 1, "exp": "120°F default to prevent scalding while controlling Legionella risk. Higher commercial settings (140°F) require mixing valves at fixtures. State scald rules in CO follow plumbing code.", "tracks": ["A", "B"], "module": 15 },

  { "id": 181, "art": "IFGC 624", "q": "Sediment trap is required on the gas connection to a:", "opts": ["Range", "Clothes dryer", "Outdoor grill", "Storage water heater"], "ans": 3, "exp": "Sediment trap required on water heater. The EXCEPTIONS list = ranges, dryers, illuminating appliances, outdoor grills. Top 12 Exam Trap #3.", "tracks": ["A", "B", "G"], "module": 15 },

  { "id": 182, "art": "IFGC 404.9", "q": "Gas piping buried outside a building in Denver must have at least how much cover?", "opts": ["6 inches", "12 inches general; 18 inches under driveways/parking areas", "24 inches always", "36 inches always"], "ans": 1, "exp": "Top 12 Exam Trap #9: 12 in general cover, 18 in under driveways and parking areas. Default to 12 unless traffic loading is in the picture.", "tracks": ["A", "B", "G"], "module": 16 },

  { "id": 183, "art": "IFGC 404.9", "q": "Gas piping buried under a Denver driveway must have at least:", "opts": ["12 in cover", "18 in cover", "24 in cover", "36 in cover"], "ans": 1, "exp": "18 in under vehicular traffic areas. 12 in general burial. Exam Trap #9 — read the scenario carefully.", "tracks": ["A", "B", "G"], "module": 16 },

  { "id": 184, "art": "IFGC 408.4", "q": "A sediment trap (drip leg) is NOT required on:", "opts": ["Storage water heater", "Boiler", "Range, clothes dryer, illuminating appliance, outdoor grill", "Furnace"], "ans": 2, "exp": "IFGC 408.4 EXCEPTIONS: ranges, clothes dryers, illuminating appliances, outdoor grills. Top 12 Exam Trap #3 — exception list is testable. All other appliances require a sediment trap (drip leg) ahead of the appliance shutoff.", "tracks": ["A", "B", "G"], "module": 16 },

  { "id": 185, "art": "IFGC 310.1", "q": "CSST (corrugated stainless steel tubing) bonding to the gas piping system must use what minimum conductor?", "opts": ["8 AWG copper", "6 AWG copper", "4 AWG copper", "12 AWG copper"], "ans": 1, "exp": "Top 12 Exam Trap #6: 6 AWG copper minimum, bonded to the gas piping system (not to CSST itself) using a clamp on a brass fitting. NEC 250.104(B) + manufacturer. Lightning damage prevention.", "tracks": ["A", "B", "G"], "module": 16 },

  { "id": 186, "art": "IFGC 409.5", "q": "An appliance gas shutoff valve must be installed:", "opts": ["Anywhere on the line", "Within 6 ft of the appliance, in the same room, accessible", "Inside the appliance", "At the meter only"], "ans": 1, "exp": "IFGC 409.5: shutoff within 6 ft, same room, accessible. Exam Trap target — students misremember as 10 ft.", "tracks": ["A", "B", "G"], "module": 16 },

  { "id": 187, "art": "IFGC Table 402.4", "q": "You're sizing 1/2-in Schedule 40 gas pipe for a 50,000 Btu/hr furnace at 30 ft developed length, 0.5 psi inlet, 0.5 in wc drop. Using the gas pipe sizing tables, this size is:", "opts": ["Always adequate", "Adequate per Table 402.4(2) — look up the run length", "Inadequate — needs 3/4 in", "Inadequate — needs 1 in"], "ans": 1, "exp": "Use Table 402.4(2) (or appropriate table for your pressure/material). At 30 ft, 1/2-in schedule 40 typically handles ~80 cfh ≈ 80 MBH — adequate for 50 MBH furnace. Always look up the table.", "tracks": ["A", "B", "G"], "module": 16 },

  { "id": 188, "art": "IFGC 402.4", "q": "Gas pipe sizing must consider:", "opts": ["Total length from meter to appliance", "Longest run from meter to farthest appliance, plus pressure drop allowance and total Btu/hr", "Just total Btu/hr", "Pipe diameter only"], "ans": 1, "exp": "Longest run method: identify the farthest appliance, sum each branch's load, look up size per Table 402.4 with the longest run as the length input. Standard ICC sizing method.", "tracks": ["A", "B", "G"], "module": 16 },

  { "id": 189, "art": "IFGC 403.4.1", "q": "Approved gas piping materials include:", "opts": ["Black steel (Schedule 40), copper (where allowed), CSST, PE (underground only)", "PVC", "Galvanized steel", "Cast iron"], "ans": 0, "exp": "IFGC 403.4: black/steel, copper (corrosion-resistant per local), CSST (listed), and PE (only underground/exterior). PVC is plumbing — not gas. Galvanized inhibits some gas additives, generally not allowed.", "tracks": ["A", "B", "G"], "module": 16 },

  { "id": 190, "art": "IFGC 415", "q": "LP gas regulator vent termination must be at least:", "opts": ["1 ft from any opening, 3 ft from ignition", "3 ft from any building opening, 5 ft from any source of ignition", "5 ft from any opening, 10 ft from ignition", "No distance — internal vent only"], "ans": 1, "exp": "IFGC: LP regulator vent terminates 3 ft from openings, 5 ft from ignition. Failed regulator can vent propane — explosion risk. Distance rules separate failure from ignition.", "tracks": ["A", "B", "G"], "module": 16 },

  { "id": 191, "art": "IFGC 406", "q": "Gas piping pressure test required before placing into service is generally:", "opts": ["1.5x operating, 10 min", "Test pressure ≥1.5x working OR 3 psig, whichever greater, held for ≥10 min, no decay", "Atmospheric only", "Soap bubble test only"], "ans": 1, "exp": "IFGC 406.4: test pressure 1.5x working pressure OR ≥3 psig (greater of), held ≥10 min with no pressure drop. Soap bubble at joints during pressurized test. Document for inspector.", "tracks": ["A", "B", "G"], "module": 16 },

  { "id": 192, "art": "IFGC 404.5", "q": "A gas pipe passing through a concrete floor slab must:", "opts": ["Be cast directly into the concrete", "Pass through a sleeve", "Be foam-wrapped", "Not pass through at all"], "ans": 1, "exp": "IFGC 404.5: sleeve through concrete to prevent corrosion from contact + allow movement. The annular space is sealed at the top. Buried-in-concrete piping fails from corrosion.", "tracks": ["A", "B", "G"], "module": 16 },

  { "id": 193, "art": "IFGC 404.6", "q": "Gas piping is prohibited from being installed:", "opts": ["In a wall", "In a chase", "In a masonry chimney", "Above a ceiling"], "ans": 2, "exp": "IFGC 404.6: gas piping NEVER in a chimney or vent. Heat + leak risk + chimney use change = explosion risk. Hard prohibition.", "tracks": ["A", "B", "G"], "module": 16 },

  { "id": 194, "art": "IFGC 404.10", "q": "Plastic (PE) gas piping is restricted to:", "opts": ["Indoor distribution only", "Underground exterior service only — risers transition to metal above grade", "Above-ground rooftop only", "All uses interchangeably with steel"], "ans": 1, "exp": "PE = polyethylene = buried gas only. Above-grade transitions to anodeless riser (metal). UV degrades PE; metal-only above grade.", "tracks": ["A", "B", "G"], "module": 16 },

  { "id": 195, "art": "IFGC 402", "q": "You have a 100 ft natural gas run, 7 in wc pressure, 0.5 in wc drop. The longest run goes to a furnace consuming 100 MBH. Using Table 402.4(1), the pipe size is:", "opts": ["1/2 in", "3/4 in", "1 in", "1-1/4 in"], "ans": 1, "exp": "At 100 ft, 7 in wc / 0.5 in drop, Table 402.4(1) shows 3/4 in delivers ~110 MBH. 1/2 in delivers ~40 MBH at this length — undersized. Always read the table by length AND load.", "tracks": ["A", "B", "G"], "module": 16 },

  { "id": 196, "art": "IFGC 310", "q": "CSST piping itself can be bonded by:", "opts": ["Clamping the conductor directly to the corrugated tubing", "Bonding to a brass fitting or metallic component of the gas piping system (NOT to the CSST tubing itself)", "Connecting only to the appliance frame", "Using a 14 AWG conductor"], "ans": 1, "exp": "Bond clamp on rigid metal pipe / brass fitting / manifold — never on the CSST corrugations (would damage). 6 AWG minimum. Top 12 Exam Trap #6.", "tracks": ["A", "B", "G"], "module": 16 },

  { "id": 197, "art": "IFGC 411", "q": "A gas connector (flexible appliance connector) length limit is:", "opts": ["3 ft general (longer types listed for specific appliances)", "6 ft for any appliance", "10 ft for ranges", "No limit if listed"], "ans": 0, "exp": "IFGC 411 / connector listings: typical 3 ft (range/dryer connectors up to 6 ft per listing). Connectors must not pass through walls, floors, ceilings.", "tracks": ["A", "B", "G"], "module": 16 },

  { "id": 198, "art": "IMC 507.12", "q": "You're installing a Type I hood over a 4-ft commercial range. The hood must overhang each open side by at least:", "opts": ["3 in", "6 in", "12 in", "18 in"], "ans": 1, "exp": "IMC 507.12: 6 in overhang on all open sides of the cooking surface for Type I hoods. Without it, plume escapes capture.", "tracks": ["A", "G"], "module": 17 },

  { "id": 199, "art": "IMC 508.1", "q": "Makeup air for a commercial Type I hood must:", "opts": ["Be provided at 100% of exhaust", "Be provided at a quantity approximately equal to exhaust (typically 80-100%), tempered as required", "Not be required", "Come from indoor air only"], "ans": 1, "exp": "IMC 508: makeup air ~ exhaust cfm, interlocked with hood fan, tempered when below 55°F per occupancy code. Imbalanced exhaust starves the building.", "tracks": ["A", "G"], "module": 17 },

  { "id": 200, "art": "IMC 507.2.1", "q": "A Type II hood is required over a:", "opts": ["Charbroiler", "Fryer", "Dishwasher (high-temp, producing steam)", "Range with open flame"], "ans": 2, "exp": "Type II = heat/moisture only (no grease): dishwashers, steamers, ovens that don't produce grease vapor. Type I covers all grease-producing equipment.", "tracks": ["A", "G"], "module": 17 },

  { "id": 201, "art": "IMC 507.11", "q": "Distance from a Type I hood to combustibles is:", "opts": ["6 in", "12 in", "18 in unless field-applied protection used", "36 in"], "ans": 2, "exp": "IMC 507.11.2: 18 in to combustibles. Field protection (sheet metal with air gap, listed shielding) can reduce. Common to all grease hood installs.", "tracks": ["A", "G"], "module": 17 },

  { "id": 202, "art": "NFPA 96", "q": "A commercial kitchen Type I hood must be equipped with:", "opts": ["A water mist system only", "A listed automatic fire-extinguishing system (typically wet chemical) and a manual pull station", "No fire suppression — sprinklers handle it", "An ABC dry chemical extinguisher nearby"], "ans": 1, "exp": "NFPA 96 + IMC 509: wet-chemical fire-extinguishing system listed for cooking grease, interlocked with fuel/electric shutoff and exhaust fan. Manual pull at exit path. Mandatory.", "tracks": ["A", "G"], "module": 17 },

  { "id": 203, "art": "IFGC 624.7", "q": "Gas connectors to commercial cooking equipment must be:", "opts": ["Standard appliance connectors, ≤3 ft", "Heavy-duty commercial connectors with restraining device and quick-disconnect", "Hard piped only", "Rubber hose"], "ans": 1, "exp": "Commercial gas connectors require quick-disconnect (so equipment can be rolled out for cleaning) plus restraining cable so the unit can't be pulled past the connector limit. NFPA 54 / IFGC 411 references.", "tracks": ["A", "G"], "module": 17 },

  { "id": 204, "art": "IMC 506", "q": "Type I hood exhaust fan must be:", "opts": ["Variable-speed only", "Upblast (centrifugal) listed for grease removal, located on the roof, away from intakes", "Any axial fan", "Inside the kitchen ceiling"], "ans": 1, "exp": "Listed upblast centrifugal grease exhaust fan, roof-mounted, hinged for access, away from intakes (10 ft routine, 30 ft hazardous). Bird-screened discharge prohibited.", "tracks": ["A", "G"], "module": 17 },

  { "id": 205, "art": "IMC 506.3.5", "q": "Cleanouts on horizontal grease duct must be every:", "opts": ["10 ft", "15 ft", "20 ft", "30 ft"], "ans": 2, "exp": "IMC 506.3.10: 20 ft maximum spacing + at every change of direction. Cleanouts critical for fire prevention.", "tracks": ["A"], "module": 17 },

  { "id": 206, "art": "IMC 507.13", "q": "The minimum exhaust airflow for a Type I hood depends on:", "opts": ["Hood length only", "Cooking equipment duty (light, medium, heavy, extra heavy) and hood style (canopy, backshelf, eyebrow)", "Building square footage", "Fan size"], "ans": 1, "exp": "IMC 507.13 + ASHRAE 154: exhaust rates by equipment duty class × hood style. Charbroilers (extra heavy) need much higher cfm than steamers (light).", "tracks": ["A", "G"], "module": 17 },

  { "id": 207, "art": "IFGC 408.4", "q": "A commercial deep fryer requires the gas line to include:", "opts": ["A sediment trap", "A bypass for cleaning", "A non-listed valve", "No special fittings"], "ans": 0, "exp": "IFGC 408.4 requires a sediment trap (drip leg) on every appliance EXCEPT the named exception list (ranges, clothes dryers, decorative-vented fireplace appliances, gas fireplaces, illuminating appliances, outdoor grills). A deep fryer is not on the exception list, so the sediment trap is required downstream of the appliance shutoff valve and as close to the inlet as practical.", "tracks": ["A", "G"], "module": 17 },

  { "id": 208, "art": "Denver DBC 2025", "q": "As of 2025-06-13, Denver permits are issued under which IMC/IFGC edition?", "opts": ["2015", "2018", "2021", "2024 (with Denver amendments)"], "ans": 3, "exp": "Denver adopted 2024 I-Codes effective 2025-06-13 (the 2025 DBC). The ICC exam may still test 2018 codes (G29 reference) — verify current exam edition before scheduling.", "tracks": ["A", "B", "G"], "module": 18 },

  { "id": 209, "art": "Denver Energy Code", "q": "Denver's energy code restricts new natural-gas connections in some occupancy categories. Always verify:", "opts": ["With Xcel Energy", "With Denver CPD for the current All-Electric / Hybrid requirements at permit application", "With the IECC alone", "With the AHJ only after rough-in"], "ans": 1, "exp": "Denver's electrification policy evolves; check Denver CPD bulletin at permit application — large commercial and multifamily new construction often require all-electric heating/water heating. Field rule, exam-adjacent.", "tracks": ["A", "B"], "module": 18 },

  { "id": 210, "art": "Denver Climate Adaptations", "q": "In Denver's high-altitude climate, derating of natural-draft gas appliances is:", "opts": ["Not necessary", "Required per manufacturer instructions for altitudes >2,000 ft above sea level", "Required only above 10,000 ft", "A myth"], "ans": 1, "exp": "Above 2,000 ft, atmospheric appliances need derating per manufacturer (typically 4% per 1,000 ft above 2,000). Denver at ~5,280 ft requires derating. Sea-level rated input ≠ Denver field input.", "tracks": ["A", "B", "G"], "module": 18 },

  { "id": 211, "art": "Denver Snow Load", "q": "Rooftop equipment supports in Denver must be designed for:", "opts": ["Wind load only", "Wind load + Denver snow load per Denver structural amendment", "No structural review", "Manufacturer's base only"], "ans": 1, "exp": "Denver structural amendment includes ground snow load values. Rooftop equipment supports per structural calc + Denver snow + wind. Larger units require sealed structural calcs.", "tracks": ["A"], "module": 18 },

  { "id": 212, "art": "Denver CPD Permit", "q": "A mechanical permit in Denver typically requires:", "opts": ["Drawings only", "Permit application, equipment list, energy compliance forms, and qualified supervisor on file", "No paperwork — inspectors decide on site", "CSLB approval"], "ans": 1, "exp": "Denver CPD requires application + plans/equipment list + energy compliance (IECC C406/R401) + listed supervisor (Class A/B/Gas). All four typically required for commercial permits.", "tracks": ["A", "B", "G"], "module": 18 },

  { "id": 213, "art": "Denver Freeze Protection", "q": "Outdoor hydronic piping in Denver must be protected against:", "opts": ["Sun damage only", "Freeze damage — insulation, glycol, or heat trace per manufacturer + Denver climate", "Wind only", "Rain only"], "ans": 1, "exp": "Sub-zero Denver winters = freeze burst risk. Required protections: insulation + heat trace OR glycol loop in unconditioned spaces. Denver amendment may add specific R-values.", "tracks": ["A", "B"], "module": 18 },

  { "id": 214, "art": "Denver Mech Inspection", "q": "Mechanical inspections in Denver are typically conducted at:", "opts": ["Final only", "Rough-in (before concealment) AND final (after startup)", "Permit issuance", "No inspection — affidavit only"], "ans": 1, "exp": "Denver CPD inspects at rough-in (duct/piping concealed) and final (operational). Larger jobs may have additional milestone inspections. Schedule via DenverGov.", "tracks": ["A", "B", "G"], "module": 18 },

  { "id": 215, "art": "Denver Combustion Air", "q": "Combustion air provisions adjusted for tight residential envelopes in Denver:", "opts": ["Allow indoor-air method always", "Generally require outdoor combustion air OR mechanical combustion air for new tight construction", "Eliminate combustion air requirements", "Use IRC residential rules only"], "ans": 1, "exp": "Modern tight construction (low infiltration) typically fails the indoor-air method volume requirement. Outdoor air or mechanical combustion air = the practical default in Denver new construction.", "tracks": ["A", "B", "G"], "module": 18 },

  { "id": 216, "art": "Denver Boiler Inspection", "q": "Boilers in Denver also fall under inspection by:", "opts": ["EPA", "Colorado Division of Oil & Public Safety (state boiler program)", "NFPA", "No state oversight"], "ans": 1, "exp": "Colorado state boiler inspection program (Division of Oil & Public Safety) administers state-level pressure vessel inspections in addition to local Denver mechanical permits. Both required.", "tracks": ["A"], "module": 18 },

  { "id": 217, "art": "Denver CPD Refrigerant", "q": "Refrigerant machinery room rules in Denver cross-reference:", "opts": ["Only IMC", "IMC Chapter 11 + IBC for occupancy classification + ASHRAE 15/34", "NFPA only", "Local fire code only"], "ans": 1, "exp": "Denver follows IMC 11 + IBC occupancy + ASHRAE 15 (safety) + ASHRAE 34 (refrigerant classification). Cross-reference all four for compliance.", "tracks": ["A"], "module": 18 },

  { "id": 218, "art": "40 CFR §82.154", "q": "Under EPA Section 608, intentionally venting refrigerant during service is:", "opts": ["Permitted for CFCs only", "Prohibited for all CFCs, HCFCs, HFCs, and substitutes (except de minimis good-faith service releases)", "Permitted up to 1 lb per service event", "Permitted with permission"], "ans": 1, "exp": "§608 (1990 + 2019 HFC amendment) prohibits knowing release. De minimis releases during good-faith service (e.g., disconnecting hoses) are tolerated, but intentional venting = violation.", "tracks": ["E"], "module": 19 },

  { "id": 219, "art": "40 CFR §82 Subpart F", "q": "EPA 608 Universal certification covers Types:", "opts": ["I + II only", "I + II + III plus Core", "Core only", "II + III only"], "ans": 1, "exp": "Universal = Core + I + II + III, each passed individually (≥18/25 on each section). Lets a technician handle all refrigerant types.", "tracks": ["E"], "module": 19 },

  { "id": 220, "art": "40 CFR §82.161", "q": "To pass EPA 608, the minimum score is:", "opts": ["60%", "70%", "72% (18 of 25 questions per section)", "80%"], "ans": 2, "exp": "18 of 25 = 72% per section. Universal requires passing each of Core/I/II/III. Failure on one section means re-taking that section.", "tracks": ["E"], "module": 19 },

  { "id": 221, "art": "40 CFR §82.157", "q": "For commercial refrigeration appliances ≥50 lb charge, leak repair is triggered at what leak rate?", "opts": ["10%", "15%", "20%", "30%"], "ans": 2, "exp": "40 CFR §82.157 (Appliance maintenance and leak repair): comfort cooling = 10%, COMMERCIAL refrigeration = 20%, industrial process = 30%. (§82.156 covers proper evacuation — different rule.) Top 12 exam trap #7. Memorize the 10/20/30 triad.", "tracks": ["E"], "module": 19 },

  { "id": 222, "art": "40 CFR §82.157", "q": "Comfort cooling systems ≥50 lb charge trigger leak repair at:", "opts": ["5%", "10%", "20%", "30%"], "ans": 1, "exp": "40 CFR §82.157: comfort cooling = 10% annual leak rate triggers repair. Lower threshold because comfort cooling is widespread (more total emissions). Commercial refrigeration = 20%, industrial process = 30%. Top 12 exam trap #7.", "tracks": ["E"], "module": 19 },

  { "id": 223, "art": "40 CFR §82.157", "q": "Industrial process refrigeration ≥50 lb charge triggers leak repair at:", "opts": ["10%", "20%", "30%", "50%"], "ans": 2, "exp": "40 CFR §82.157: industrial process = 30% — the highest threshold (industrial systems naturally leak more). Memorize 10/20/30 for comfort/commercial/industrial. Top 12 exam trap #7.", "tracks": ["E"], "module": 19 },

  { "id": 224, "art": "40 CFR §82.156", "q": "Once a leak is detected exceeding the trigger rate, the repair must be completed within:", "opts": ["7 days", "14 days", "30 days", "60 days"], "ans": 2, "exp": "30 days to complete initial repair after detection (extensions available for parts/access). Failure to repair = continued enforcement liability.", "tracks": ["E"], "module": 19 },

  { "id": 225, "art": "40 CFR §82.150", "q": "Recovery, recycling, and reclamation are three different processes. Reclamation requires:", "opts": ["Removing refrigerant only", "Reprocessing to ARI 700 specifications by a certified reclaimer", "Field filtration only", "Mixing virgin with recovered"], "ans": 1, "exp": "Recovery = pull out of system. Recycle = field clean (filter, separate oil). Reclaim = reprocess to ARI/AHRI 700 virgin specs at certified facility. Required after sale or before refilling another owner's system.", "tracks": ["E"], "module": 19 },

  { "id": 226, "art": "Clean Air Act §608", "q": "Ozone Depletion Potential (ODP) uses CFC-12 as the reference value of:", "opts": ["0.1", "1.0", "10", "100"], "ans": 1, "exp": "CFC-12 ODP = 1.0 (reference). HCFCs are fractional (R-22 ≈ 0.05). HFCs ODP = 0 (no chlorine). Distinguish ODP from GWP — different metrics.", "tracks": ["E"], "module": 19 },

  { "id": 227, "art": "40 CFR §82.156", "q": "Refrigerant containers larger than 2 lb may be sold to:", "opts": ["Anyone", "Section 608 certified technicians only (proof required)", "Homeowners with receipt", "Anyone over 18"], "ans": 1, "exp": "§608 sales restriction: refrigerants in containers >2 lb sold only to certified technicians. Suppliers must verify certification (kept on file). Prevents DIY release.", "tracks": ["E"], "module": 19 },

  { "id": 228, "art": "40 CFR §82.156", "q": "The final person in the disposal chain of a refrigerated appliance must:", "opts": ["Cut the lines", "Recover the refrigerant or verify recovery was performed", "Crush the unit", "Notify EPA"], "ans": 1, "exp": "§608 disposal rule: final person (e.g., scrap yard) must recover OR have signed statement that recovery was already performed. Records kept 3 years.", "tracks": ["E"], "module": 19 },

  { "id": 229, "art": "40 CFR §82.161", "q": "Recovery equipment manufactured after November 15, 1993 must be:", "opts": ["Certified by the manufacturer only", "Certified to meet EPA recovery efficiency standards", "ARI listed only", "Just UL listed"], "ans": 1, "exp": "§608: post-Nov 15, 1993 recovery equipment must be EPA-certified to recovery efficiency standards (varies by appliance type). Old equipment grandfathered but may not meet modern efficiency.", "tracks": ["E"], "module": 19 },

  { "id": 230, "art": "Clean Air Act §608 + AIM Act", "q": "The American Innovation and Manufacturing (AIM) Act of 2020 affects refrigerants by:", "opts": ["Banning all refrigerants", "Phasing down HFCs (high-GWP) production and consumption over 15 years", "Replacing §608", "Eliminating EPA jurisdiction"], "ans": 1, "exp": "AIM Act 2020: 85% HFC phasedown by 2036. Complements §608. Drives transition to A2L (R-32, R-454B) and natural refrigerants. Tested on modern 608 versions.", "tracks": ["E"], "module": 19 },

  { "id": 231, "art": "40 CFR §82", "q": "Chlorine atoms catalytically destroy ozone — one Cl atom destroys approximately:", "opts": ["1 O3 molecule", "100 O3 molecules", "10,000 O3 molecules", "100,000 O3 molecules"], "ans": 3, "exp": "~100,000 ozone molecules per Cl before scavenged. Catalytic cycle = why CFCs are so destructive despite small atmospheric concentrations. HFCs (no Cl) = ODP 0.", "tracks": ["E"], "module": 19 },

  { "id": 232, "art": "40 CFR §82", "q": "Recovery technician certification records must be:", "opts": ["Held by EPA", "Held by the technician AND/OR employer; available for inspection", "Discarded after 1 year", "Public record"], "ans": 1, "exp": "Technician keeps card; employer keeps copy; available for EPA inspection. Lost card = re-issue from certifier. Practice rule: keep card on truck.", "tracks": ["E"], "module": 19 },

  { "id": 233, "art": "Refrigerant Identification", "q": "R-22 is classified chemically as:", "opts": ["CFC", "HCFC", "HFC", "HFO"], "ans": 1, "exp": "R-22 = chlorodifluoromethane = HCFC (chlorine + hydrogen + fluorine). Phased out for new equipment 2010, production phaseout 2020. Replaced by R-410A (HFC).", "tracks": ["E"], "module": 19 },

  { "id": 234, "art": "40 CFR §82.152", "q": "EPA 608 Type I certification covers small appliances. The 5-pound rule means:", "opts": ["Equipment under 5 lb total weight", "Appliances manufactured, charged, and HERMETICALLY SEALED at the factory with ≤5 lb refrigerant", "Any system with under 5 lb of charge", "Anything with a copper line"], "ans": 1, "exp": "Top 12 Exam Trap #8: Type I = small appliances ≤5 lb FACTORY-SEALED. A field-charged 4-lb unit does NOT qualify as Type I. Hermetic factory seal is required.", "tracks": ["E"], "module": 20 },

  { "id": 235, "art": "40 CFR §82.158", "q": "For Type I small appliances with the compressor OPERATING during recovery, required recovery efficiency is:", "opts": ["80%", "85%", "90%", "100%"], "ans": 2, "exp": "Type I recovery: 90% if compressor runs, 80% if compressor doesn't run (or won't run). Compressor helps pump refrigerant into the recovery machine.", "tracks": ["E"], "module": 20 },

  { "id": 236, "art": "40 CFR §82.158", "q": "For Type I small appliances when the compressor does NOT operate, required recovery efficiency is:", "opts": ["70%", "80%", "90%", "100%"], "ans": 1, "exp": "80% if compressor inoperative. Two recovery efficiency standards for Type I — distinguish based on compressor condition.", "tracks": ["E"], "module": 20 },

  { "id": 237, "art": "40 CFR §82.152", "q": "Which appliance is a typical Type I example?", "opts": ["10-ton commercial chiller", "Window air conditioner with factory-sealed 3-lb R-32 charge", "50-lb supermarket rack", "Centrifugal chiller"], "ans": 1, "exp": "Window unit, mini-fridge, household refrigerator, dehumidifier, drinking fountain — all factory-sealed with ≤5 lb. Type I work. Larger or field-charged = Type II or III.", "tracks": ["E"], "module": 20 },

  { "id": 238, "art": "40 CFR §82.152", "q": "A residential refrigerator with a field-charged 4.5-lb R-134a charge qualifies for what EPA certification?", "opts": ["Type I — because it's under 5 lb", "Type II — because it's field-charged (not factory-sealed) regardless of charge size", "Type III", "Universal only"], "ans": 1, "exp": "Type I requires FACTORY-SEALED hermetic with ≤5 lb. Field-charged means it's an open system in EPA terms → Type II (high-pressure). Exam Trap #8 — students lock onto the 5-lb number.", "tracks": ["E"], "module": 20 },

  { "id": 239, "art": "40 CFR §82.156", "q": "A Type I appliance owner disposing of a refrigerator must:", "opts": ["Recover refrigerant or verify recovery was performed before final disposal", "Cut the lines", "Crush the unit", "Donate it"], "ans": 0, "exp": "Disposal: refrigerant recovered before final destruction; signed statement to scrap yard. Owner/final-processor liability under §608.", "tracks": ["E"], "module": 20 },

  { "id": 240, "art": "40 CFR §82.156", "q": "Recovery equipment for Type I work must:", "opts": ["Be EPA-certified for small appliance recovery and meet 90%/80% efficiency standards", "Be any vacuum pump", "Have a 5 hp motor", "Be brand new"], "ans": 0, "exp": "Listed/certified Type I recovery machines. Manufactured after Nov 15, 1993 must meet the 90/80 standard. Recovery machine is the technician's most regulated tool.", "tracks": ["E"], "module": 20 },

  { "id": 241, "art": "40 CFR §82.158", "q": "A self-contained recovery machine that meets BOTH compressor-on and compressor-off standards for Type I can be used:", "opts": ["Only when compressor runs", "Only when compressor doesn't run", "Either condition", "Never on R-410A"], "ans": 2, "exp": "Self-contained recovery machines compatible with both conditions are required for general Type I work — many small appliances arrive non-operational at the shop.", "tracks": ["E"], "module": 20 },

  { "id": 242, "art": "40 CFR §82.166", "q": "A technician working only on Type I appliances needs which certification(s)?", "opts": ["Universal", "Type I only", "Core + Type I", "Core only"], "ans": 2, "exp": "Core (universal foundation) + Type I (small appliance specific). Core is the foundational module; ALL technicians need it. Type I alone is meaningless — Core must accompany.", "tracks": ["E"], "module": 20 },

  { "id": 243, "art": "40 CFR §82.156", "q": "A refrigerator is being scrapped. Its label shows 'no refrigerant remaining — recovered Mar 2024 by Tech ID 12345.' The scrap yard may:", "opts": ["Accept the unit on the strength of the signed statement", "Re-recover regardless", "Refuse the unit", "Send to landfill without recovery"], "ans": 0, "exp": "Signed statement with prior tech's ID + date is acceptable proof. Final processor keeps record (3 yr). One of the few cases where chain of custody substitutes for re-recovery.", "tracks": ["E"], "module": 20 },

  { "id": 244, "art": "40 CFR §82", "q": "For Type I work, recovery typically uses what approach?", "opts": ["Passive bag method", "Active recovery machine OR EPA-approved passive recovery (rare for old units only)", "Open venting", "Pump down to atmosphere"], "ans": 1, "exp": "Active recovery is the norm; some older small appliances (single-pass system access methods) had passive recovery options that EPA mostly retired. Active = compliant.", "tracks": ["E"], "module": 20 },

  { "id": 245, "art": "40 CFR §82.156", "q": "Records of Type I appliance disposal must be kept for:", "opts": ["1 year", "3 years", "5 years", "Forever"], "ans": 1, "exp": "§608 records (disposal, recovery, technician certs) = 3 years minimum, available for EPA inspection. Common record-keeping period across §608.", "tracks": ["E"], "module": 20 },

  { "id": 246, "art": "40 CFR §82.158 Table", "q": "For a high-pressure appliance with ≥200 lb charge (Type II), required recovery vacuum is:", "opts": ["0 in Hg", "10 in Hg vacuum", "15 in Hg vacuum", "25 in Hg vacuum"], "ans": 1, "exp": "≥200 lb charge: 10 in Hg vacuum (for current/post-Nov 1993 recovery equipment). <200 lb has different thresholds (down to 0 psig). Memorize the table by charge size.", "tracks": ["E"], "module": 21 },

  { "id": 247, "art": "40 CFR §82.158 Table", "q": "For high-pressure systems (Type II) with charge <200 lb, required recovery level is:", "opts": ["0 psig (or up to 0 in Hg per equipment vintage)", "10 in Hg vacuum", "25 in Hg vacuum", "No requirement"], "ans": 0, "exp": "<200 lb HP appliance: recover to 0 psig (atmospheric) per the post-Nov 1993 standard. ≥200 lb tightens to 10 in Hg. Easy to confuse with low-pressure (Type III) 25 in Hg requirement.", "tracks": ["E"], "module": 21 },

  { "id": 248, "art": "40 CFR §82", "q": "R-410A is classified as Type:", "opts": ["I", "II (high-pressure)", "III", "Universal only"], "ans": 1, "exp": "R-410A = high-pressure refrigerant (Type II domain). Operating pressures higher than R-22. Type II certification required for service.", "tracks": ["E"], "module": 21 },

  { "id": 249, "art": "40 CFR §82", "q": "You're servicing a commercial 60-lb R-410A rooftop unit. Recovery must achieve:", "opts": ["10 in Hg vacuum", "0 psig per Type II <200 lb standard", "25 in Hg", "No recovery — top off only"], "ans": 1, "exp": "60 lb < 200 lb threshold → 0 psig recovery. Above 200 lb tightens to 10 in Hg. Always check charge size before reading the table.", "tracks": ["E"], "module": 21 },

  { "id": 250, "art": "40 CFR §82", "q": "You're recharging an A2L system (R-32) in a commercial setting. Required safety practices include:", "opts": ["Same as A1 — no changes", "Ventilation, leak detection, NO open flames during service, A2L-rated recovery equipment", "No special practices", "Vent test gas to atmosphere"], "ans": 1, "exp": "A2L (mildly flammable): ventilation, leak detection, no ignition sources, listed A2L recovery equipment, and electrical work per manufacturer's safety supplement. Critical for modern refrigerant transitions.", "tracks": ["E"], "module": 21 },

  { "id": 251, "art": "ASHRAE 34 / 40 CFR §82", "q": "R-454B is increasingly used to replace R-410A in new equipment. Its safety class is:", "opts": ["A1", "A2L", "B1", "A3"], "ans": 1, "exp": "R-454B = A2L (mildly flammable, low toxicity). Lower GWP than R-410A (~75% reduction). Requires updated install practices.", "tracks": ["E"], "module": 21 },

  { "id": 252, "art": "40 CFR §82.157", "q": "Leak rate for a commercial 100-lb R-410A refrigeration rack triggers repair if it exceeds:", "opts": ["10%", "20%", "30%", "50%"], "ans": 1, "exp": "40 CFR §82.157: commercial refrigeration leak rate trigger = 20% (the 100 lb charge is ≥50 lb so the rule applies). Comfort cooling = 10%, industrial process = 30%. Top 12 exam trap #7.", "tracks": ["E"], "module": 21 },

  { "id": 253, "art": "40 CFR §82.157", "q": "A leak inspection on a ≥500-lb commercial refrigeration system found leak rate >20%. Required follow-up includes:", "opts": ["No follow-up needed", "Initial leak verification, repair within 30 days, and follow-up verification testing", "Just record the leak", "Notify customer only"], "ans": 1, "exp": "§82.157: detect/verify → repair within 30 days → verification test (initial + follow-up). Documentation in records. Industrial process triggers tighter timelines.", "tracks": ["E"], "module": 21 },

  { "id": 254, "art": "40 CFR §82", "q": "Refrigerant cylinders must be DOT-certified and:", "opts": ["Reusable indefinitely", "Pressure tested per DOT schedule (typically 5 yr re-test); recovery cylinders 80% fill limit", "Never re-used", "Plastic acceptable"], "ans": 1, "exp": "DOT cylinder re-test every 5 yr (date stamped). Recovery cylinders limited to 80% liquid fill at 130°F (overpressure safety). Critical knowledge for safe transport.", "tracks": ["E"], "module": 21 },

  { "id": 255, "art": "40 CFR §82", "q": "You evacuate a high-pressure system before brazing. Best practice is to evacuate to:", "opts": ["0 psig", "Triple-evacuate to deep vacuum (≤500 microns) with nitrogen purge between evacuations", "Recovery only — no vacuum", "Atmospheric"], "ans": 1, "exp": "For service (not just §608 recovery), triple evacuation with dry nitrogen purge to ≤500 microns ensures moisture/non-condensables removed. Distinguish §608 recovery (legal min) vs service practice (deep vacuum).", "tracks": ["E"], "module": 21 },

  { "id": 256, "art": "40 CFR §82.158", "q": "A non-self-contained recovery system (uses the appliance's compressor) recovers refrigerant by:", "opts": ["Pumping with the appliance's compressor while pulling vacuum on the receiver", "Heating the refrigerant", "Vibrating the lines", "Compressed air injection"], "ans": 0, "exp": "System-dependent recovery uses appliance compressor to push refrigerant into recovery cylinder. Faster than passive but requires functional compressor. Type II/III work.", "tracks": ["E"], "module": 21 },

  { "id": 257, "art": "40 CFR §82", "q": "Refrigerants must be properly labeled in storage. A recovery cylinder containing R-410A must:", "opts": ["Have only a 'recovered' tag", "Be color-coded (e.g., gray) AND labeled with refrigerant type AND marked as recovered", "Be unlabeled", "Match the appliance label color"], "ans": 1, "exp": "Recovery cylinders: gray with yellow shoulder (typical), labeled with refrigerant and recovery status, marked 'CONTAINS USED REFRIGERANT.' Mislabeling = enforcement risk.", "tracks": ["E"], "module": 21 },

  { "id": 258, "art": "40 CFR §82", "q": "You discover an R-22 system mixed with R-410A. The proper action is:", "opts": ["Recover the mix and label as 'mixed refrigerant' for reclaim", "Vent it", "Use it for another system", "Continue operating"], "ans": 0, "exp": "Mixed refrigerants cannot be reused or vented. Recover into separate cylinder labeled 'MIXED' for return to reclaimer (often disposed/destroyed). Document carefully — mixed refrigerant = lost product.", "tracks": ["E"], "module": 21 },

  { "id": 259, "art": "40 CFR §82", "q": "Sales of small (<2 lb) containers of HFC refrigerant:", "opts": ["Are restricted to §608 certified technicians", "Are unrestricted to the general public for self-service (subject to recovery rules)", "Are illegal", "Require state license"], "ans": 1, "exp": "<2 lb containers (typical DIY automotive AC top-off) are not restricted to certified technicians under §608, BUT venting prohibition still applies. >2 lb = certified-only.", "tracks": ["E"], "module": 21 },

  { "id": 260, "art": "40 CFR §82.158 Table", "q": "Low-pressure (Type III) refrigerants like R-123 require recovery to what vacuum level?", "opts": ["0 in Hg", "10 in Hg vacuum", "25 mm Hg absolute (≈29 in Hg vacuum)", "Atmospheric only"], "ans": 2, "exp": "Type III low-pressure: 25 mm Hg absolute = ~29 in Hg vacuum. Very deep vacuum because low-pressure refrigerants are at sub-atmospheric pressure in normal operation.", "tracks": ["E"], "module": 22 },

  { "id": 261, "art": "40 CFR §82", "q": "R-123 (HCFC) is classified by ASHRAE 34 as:", "opts": ["A1", "A2L", "B1", "B2"], "ans": 2, "exp": "R-123 = B1: higher toxicity (B class), no flame propagation (1). Common in centrifugal chillers (large commercial). Production phaseout HCFC.", "tracks": ["E"], "module": 22 },

  { "id": 262, "art": "40 CFR §82", "q": "A centrifugal chiller using R-123 has a purge unit because:", "opts": ["The system operates below atmospheric pressure, allowing air to leak IN", "To increase pressure", "To cool the operator", "Decoration"], "ans": 0, "exp": "Low-pressure chillers run below atmospheric → leaks pull air (and moisture) INTO the system. Purge unit removes non-condensables. Modern purge units have very low refrigerant loss.", "tracks": ["E"], "module": 22 },

  { "id": 263, "art": "40 CFR §82.158", "q": "Purge units on low-pressure chillers manufactured after Nov 15, 1993 must have:", "opts": ["No emission standard", "Refrigerant emission limit (typically <0.1 lb per lb of air purged)", "Unrestricted venting", "Manual operation only"], "ans": 1, "exp": "Modern purge units engineered for very low refrigerant loss (high-efficiency purge). Older purges lost significant refrigerant per cycle — replaced or rebuilt during R-123 retrofits.", "tracks": ["E"], "module": 22 },

  { "id": 264, "art": "40 CFR §82", "q": "R-1233zd is a modern low-pressure refrigerant. It is classified as:", "opts": ["A1", "A2L", "B1", "B2"], "ans": 0, "exp": "R-1233zd = A1 (low toxicity, no flame). HFO replacement for R-123 in centrifugal chillers. Lower GWP. Reverses some legacy concerns about B-class toxicity.", "tracks": ["E"], "module": 22 },

  { "id": 265, "art": "40 CFR §82.157", "q": "Comfort cooling leak rate trigger for a 150-lb low-pressure chiller is:", "opts": ["10%", "20%", "30%", "No trigger"], "ans": 0, "exp": "40 CFR §82.157: leak trigger is set by SYSTEM USE not pressure class. A chiller serving HVAC = comfort cooling = 10%. Commercial refrigeration = 20%, industrial process = 30%. Top 12 exam trap #7.", "tracks": ["E"], "module": 22 },

  { "id": 266, "art": "40 CFR §82", "q": "Pump-out operations for low-pressure systems require:", "opts": ["Standard high-pressure recovery equipment", "Recovery equipment certified for low-pressure systems (deep vacuum capable)", "Open venting", "Hand pumping"], "ans": 1, "exp": "Low-pressure systems require equipment that can pull ~29 in Hg vacuum. Standard high-pressure recovery units may not be capable. Listed low-pressure recovery systems are different equipment.", "tracks": ["E"], "module": 22 },

  { "id": 267, "art": "40 CFR §82", "q": "Recovery from a low-pressure chiller normally requires:", "opts": ["Less time than high-pressure work", "More time — moving large volumes of low-density refrigerant gas takes longer", "Same time", "Vacuum is achieved instantly"], "ans": 1, "exp": "Low-density vapor + deep vacuum = long recovery times (sometimes days for large chillers). Plan service accordingly. Common Type III field reality.", "tracks": ["E"], "module": 22 },

  { "id": 268, "art": "40 CFR §82", "q": "A centrifugal chiller using R-1233zd would be tagged with what safety information?", "opts": ["No tag needed", "Refrigerant type + charge + classification + ASHRAE 15 machinery room compliance", "Color stripe only", "Manufacturer's logo only"], "ans": 1, "exp": "ASHRAE 15 + IMC 1106 require nameplate with refrigerant type, charge (lb), safety class, and machinery room compliance. Critical for emergency responders + future technicians.", "tracks": ["E"], "module": 22 },

  { "id": 269, "art": "40 CFR §82", "q": "Charging a low-pressure system requires:", "opts": ["High-pressure recovery cylinders", "Specific low-pressure charging equipment + the system must be evacuated before charging", "Just pour it in", "Pressurize with nitrogen first"], "ans": 1, "exp": "Low-pressure systems charged via dedicated equipment after deep evacuation. Mismatched equipment can damage the chiller or introduce contamination. Specialized work.", "tracks": ["E"], "module": 22 },

  { "id": 270, "art": "40 CFR §82.158 Table", "q": "Quick recap — low-pressure (Type III) recovery vacuum requirement is:", "opts": ["10 in Hg vacuum", "25 mm Hg absolute (≈29 in Hg vacuum)", "0 psig", "No requirement"], "ans": 1, "exp": "25 mm Hg absolute = the Type III standard. Distinct from Type II (0 psig or 10 in Hg) and Type I (90%/80% efficiency). Three separate standards by refrigerant class.", "tracks": ["E"], "module": 22 },

  { "id": 271, "art": "40 CFR §82", "q": "You are a contractor with Type II certification but not Type III. You may:", "opts": ["Service centrifugal chillers using R-123", "Service only high-pressure refrigerants (not low-pressure)", "Service any refrigeration system", "Have a tech work under your card"], "ans": 1, "exp": "Each certification is independent. Type II ≠ Type III. Universal = all four. For low-pressure chiller work, Type III is required. No 'borrowing' another tech's card.", "tracks": ["E"], "module": 22 },
];

// Quick-reference exam pool keyed by track for the app's quiz UI
export const HVAC_EXAM_POOL_A = HVAC_ALL_QUESTIONS.filter(q => q.tracks.includes("A"));
export const HVAC_EXAM_POOL_B = HVAC_ALL_QUESTIONS.filter(q => q.tracks.includes("B"));
export const HVAC_EXAM_POOL_G = HVAC_ALL_QUESTIONS.filter(q => q.tracks.includes("G"));
export const HVAC_EXAM_POOL_E = HVAC_ALL_QUESTIONS.filter(q => q.tracks.includes("E"));
